/* LISTENING (second doubling, set B) — Conversations vzb001-vzb029 (peers, work, services, social) and Academic Talks tzb001-tzb016 (economics, finance, accounting, behavioral and social science, history, humanities) */
(function () {
  CONTENT.conv.push(
    { id: "vzb001", diff: 2, ctx: "Listen to a conversation between two coworkers at a university gym.", names: {W:"Woman",M:"Man"}, lines: [
      ["M", "Hey, Priya, have you got a second? I need a huge favor."],
      ["W", "That depends. Is it the kind of favor that involves my Saturday?"],
      ["M", "Sort of, yes. My cousin is getting married in Leeds on the twenty-first, and I'm down for the opening shift at the front desk that morning."],
      ["W", "The six-thirty one? Ugh. You know I'm not a morning person."],
      ["M", "I know, I know. But I'd take your Thursday evening shift in exchange, so you'd get that night free."],
      ["W", "Thursday evening is actually tempting, because I have a seminar on Friday morning and I haven't even opened the reading. But did you ask Mr. Okoye? He has to approve any swap."],
      ["M", "I mentioned it, and he said it's fine as long as the person covering has done the keycard training. That's you, me, and Tom."],
      ["W", "And Tom is away that week. So it has to be me."],
      ["M", "Exactly. So, is that a yes?"],
      ["W", "It's a yes. Send Mr. Okoye an email so the swap is official, and put me in copy."],
      ["M", "Will do. Thank you, Priya, I owe you one."]],
      qs: [
      { q: "Why does the man talk to the woman?", o: ["He wants her to train a new employee at the front desk.","He wants to complain about the way Mr. Okoye plans shifts.","He wants to invite her to his cousin's wedding in Leeds.","He wants her to cover his Saturday morning shift."], a: 3, x: "Il explique que son cousin se marie le samedi, quand il est de service : il demande un échange de créneau. L'invitation au mariage est un piège (mot répété)." },
      { q: "What does the man offer in return?", o: ["To buy her breakfast before the early shift.","To work her Sunday closing for a month.","To take over her Thursday evening shift.","To lend her his notes for the Friday seminar."], a: 2, x: "« I'd take your Thursday evening shift in exchange ». Les autres propositions ne sont jamais faites." },
      { q: "What does the woman imply when she says Thursday evening is \"actually tempting\"?", o: ["She would like a free evening to prepare for her seminar.","She prefers working in the evening to working in the morning.","She has no other plans on Thursday and wants extra hours.","She wants to spend more time with the man on Thursdays."], a: 0, x: "Elle enchaîne : séminaire vendredi, lecture pas commencée. Ce qui la tente, c'est de libérer sa soirée pour travailler, pas de gagner des heures." }
      ] },
    { id: "vzb002", diff: 3, ctx: "Listen to a conversation between a student and her landlord.", names: {W:"Student",M:"Landlord"}, lines: [
      ["W", "Mr. Brennan, thanks for seeing me. I got the statement for my deposit, and there's a deduction of two hundred and eighty pounds for carpet replacement. I'd like to understand that."],
      ["M", "Of course. When I did the walk-through on Friday, there was a large stain in the bedroom, right by the window. That carpet was fairly new, so I had to get a price for replacing it."],
      ["W", "Right, but if I may, that stain was there when I moved in. It's on the inventory I signed in September: bedroom, carpet, minor mark near window."],
      ["M", "Minor mark. What I saw wasn't minor. It had spread. It was about the size of a dinner plate."],
      ["W", "It may have spread a little, but I've been using that room as a bedroom, not a laboratory. Some fading from sunlight and foot traffic is what the tenancy guide calls fair wear and tear, isn't it?"],
      ["M", "Wear and tear, yes, but not damage. I'm afraid the line between the two is exactly what we're arguing about."],
      ["W", "Then can I suggest a compromise? Send me the photos from the inventory and the invoice from whoever dealt with it. If the stain has clearly grown, I'll accept paying a share of the cost. But not a whole carpet."],
      ["M", "Hmm. Well, actually, I haven't replaced anything yet. I had it cleaned, and the cleaners said it came out mostly. The figure on the statement was from a quote for replacement."],
      ["W", "So the deduction is based on a quote, not on money you've actually spent?"],
      ["M", "Strictly speaking, yes. Let me find the cleaning invoice and I'll revise the statement. You'll have an email by Wednesday."]],
      qs: [
      { q: "Why does the student meet with her landlord?", o: ["To ask him to replace the carpet in her bedroom.","To dispute a charge taken from her deposit.","To negotiate a lower rent for the coming year.","To report damage that was there before she moved in."], a: 1, x: "Elle conteste une retenue de 280 livres. Le dernier choix est un piège : la tache préexistante est un argument, pas le but de la visite." },
      { q: "What does the student claim about the stain?", o: ["It was caused by the cleaners whom the landlord had hired in October.","It was too small to be visible when she first looked at the room.","It appeared only after the landlord's walk-through on Friday morning.","It was already recorded on the inventory she signed in September."], a: 3, x: "« It's on the inventory I signed in September ». Elle ne dit pas que la tache était invisible, mais qu'elle était déjà notée." },
      { q: "What does the landlord's last explanation suggest?", o: ["He still believes that the stain is her responsibility.","He charged her for a cost he has not actually had.","He will replace the carpet at his own expense.","He has already sent the invoice to the cleaners."], a: 1, x: "Il avoue avoir seulement fait nettoyer la moquette et s'être appuyé sur un devis : la retenue ne correspond à aucune dépense réelle. Il ne renonce pas pour autant à tout débat sur la tache." }
      ] },
    { id: "vzb003", diff: 4, ctx: "Listen to a conversation between two students.", names: {W:"Woman",M:"Man"}, lines: [
      ["W", "So Marcus has asked you to be \"chief financial officer\" of a company that doesn't have any finances."],
      ["M", "Technically it has a logo and a domain name. He's very proud of the domain name."],
      ["W", "Well, that's two more assets than I'd have predicted. What's the pitch?"],
      ["M", "An app that matches people who want to swap textbooks. Which, I know, sounds like something that already exists, several times over."],
      ["W", "It does exist. It's called the noticeboard in the student union."],
      ["M", "Okay, laugh. But the thing is, he isn't asking me for money. He's asking for ten hours a week in exchange for equity. Four percent."],
      ["W", "Four percent of nothing is, as you will doubtless calculate, nothing. Unless it turns out not to be nothing, in which case it gets diluted into a different kind of nothing by the first funding round."],
      ["M", "That's unfair. Somebody has to be there at the beginning, or no company would ever exist."],
      ["W", "Sure. But I'd say beginnings come in two flavors: the ones where people have found a real problem, and the ones where people have a real friend. I suspect this is the second."],
      ["M", "Hm. That's a bit harsh. Though I'll admit I said yes partly because I didn't want to let him down."],
      ["W", "Which is a perfectly decent reason to help someone. It's just not a business plan. Do the ten hours, by all means. But call it a favor, and keep your Thursday evenings."]],
      qs: [
      { q: "What are the speakers mainly discussing?", o: ["Whether the man should give his time to a friend's unproven business.","How the man can raise enough money to launch a textbook exchange app.","Why the student union has never updated its old textbook noticeboard.","Which of the two friends ought to become the new company's director."], a: 0, x: "Toute la conversation tourne autour de la proposition de Marcus et de sa valeur réelle ; il ne s'agit ni de lever des fonds ni de désigner un dirigeant." },
      { q: "What is Marcus offering the man?", o: ["A fixed weekly salary in return for ten hours of accounting work.","A fixed share of the money raised in the first funding round.","A four percent share of the company for ten hours of work a week.","A four percent commission on every textbook swapped through the app."], a: 2, x: "« ten hours a week in exchange for equity. Four percent ». Il n'y a ni salaire ni commission, et pas encore de levée de fonds." },
      { q: "What does the woman suggest by distinguishing a \"real problem\" from a \"real friend\"?", o: ["The man should find a friend who understands finance.","Marcus has identified a problem that no one else has noticed.","The project seems driven more by loyalty than by demand.","The app would only appeal to people who know Marcus."], a: 2, x: "Elle oppose deux motivations de départ et soupçonne la seconde : l'amitié, pas un vrai besoin du marché. Elle ne remet pas en cause la sincérité de l'homme." }
      ] },
    { id: "vzb004", diff: 2, ctx: "Listen to a conversation between a student and a bank teller.", names: {W:"Teller",M:"Student"}, lines: [
      ["M", "Hi, I'd like to open a student account, please. I only arrived from Brazil this month."],
      ["W", "Welcome! Do you have your passport and a proof of address?"],
      ["M", "I have my passport and my student card. For the address, I only have a letter from the university housing office. Is that enough?"],
      ["W", "Yes, that's fine, as long as it's dated within the last three months. Let me check. Yes, this one is from last week. Perfect. Now, will you be receiving money from abroad?"],
      ["M", "Yes, my parents will send me money every month. Is there a fee for that?"],
      ["W", "Receiving international transfers is free with this account, but the sender's bank may charge them. If your parents use our partner bank in Brazil, their fee is lower."],
      ["M", "I'll tell them. And is there a monthly charge for the account?"],
      ["W", "Not for students. It's free while you're enrolled, but we need a new proof of enrollment every September to keep it that way."],
      ["M", "Good to know. And when will I get my debit card?"],
      ["W", "It'll arrive at your address in five to seven working days. In the meantime, you can use the mobile app."]],
      qs: [
      { q: "Why does the student visit the bank?", o: ["To open an account for his studies.","To transfer money to his parents in Brazil.","To ask for a loan to pay for housing.","To replace a debit card he has lost."], a: 0, x: "Dès la première phrase : « I'd like to open a student account »." },
      { q: "What does the teller say about international transfers?", o: ["The bank charges a small fee unless the money comes from Brazil.","The bank does not charge for them, but the sender's bank might.","Only transfers from the partner bank in Brazil are accepted.","Both banks charge the same fee, so the amount is not important."], a: 1, x: "« Receiving ... is free ... but the sender's bank may charge them ». La banque partenaire réduit seulement les frais de l'expéditeur." },
      { q: "What can be inferred about the letter from the housing office?", o: ["It must be replaced by a bank statement.","It proves that the student is enrolled in September.","It is too old to be accepted as a proof of address.","It can be used because it is recent enough."], a: 3, x: "La règle est « dated within the last three months » et la lettre date de la semaine dernière : elle convient. Le justificatif d'inscription est une autre exigence (chaque septembre)." }
      ] },
    { id: "vzb005", diff: 3, ctx: "Listen to a conversation between a student and a travel agent.", names: {W:"Travel agent",M:"Student"}, lines: [
      ["M", "Hi, my flight to Madrid tomorrow morning has been cancelled. The airline's email says to contact my booking agent, which I guess is you."],
      ["W", "It is. Let me have a look. Yes, I can see it. The airline cancelled because of the air-traffic controllers' strike. They can put you on Thursday's flight, or refund you."],
      ["M", "Thursday is no good. I'm presenting at a conference on Wednesday afternoon. Is there anything on Tuesday evening?"],
      ["W", "There's a connection via Frankfurt that gets you in at one in the morning. It's a hundred and ten euros more, though."],
      ["M", "I took the travel insurance when I booked. Doesn't that cover the difference?"],
      ["W", "Let me check the policy. Hmm. It covers delay and cancellation, but there's an exclusion for industrial action announced before the date of purchase. When did you book?"],
      ["M", "Three weeks ago. And the strike was only announced on Monday."],
      ["W", "In that case you should be fine, since the announcement came after you bought it. Still, keep every receipt, and ask the airline for a written statement of why they cancelled. Insurers love paperwork."],
      ["M", "So I take the Frankfurt route and claim the difference afterwards?"],
      ["W", "That's what I'd do. I can hold the seat for an hour while you decide."]],
      qs: [
      { q: "What problem does the student have?", o: ["His travel insurance has run out and he needs a new policy before he can travel.","His booking was lost and the airline cannot find his reservation for tomorrow.","His flight was cancelled, and he has to reach Madrid for a presentation.","His connection in Frankfurt is too short and he will miss the flight to Madrid."], a: 2, x: "Il doit arriver à Madrid avant sa présentation de mercredi. Francfort est la solution proposée, pas le problème." },
      { q: "Why does the student reject the Thursday flight?", o: ["He cannot afford to stay in Madrid for an extra night.","He has to speak at a conference the day before.","He has another flight booked with the same airline.","He needs to be home to meet his insurance adviser."], a: 1, x: "« I'm presenting at a conference on Wednesday afternoon » : un vol jeudi arriverait trop tard." },
      { q: "Why does the agent ask when the student bought his ticket?", o: ["To find out whether the strike exclusion in the policy applies.","To check that he is still within the period allowed for a refund.","To decide whether the airline owes him compensation for the delay.","To see whether he booked early enough to get a cheaper connection."], a: 0, x: "L'exclusion ne vise que les grèves annoncées avant l'achat. Il a réservé trois semaines avant l'annonce : l'assurance devrait donc couvrir." }
      ] },
    { id: "vzb006", diff: 4, ctx: "Listen to a conversation between two interns at a consulting firm.", names: {W:"Hana",M:"Joel"}, lines: [
      ["W", "Joel, do you have a sec? It's, um, a bit awkward, and I'd rather say it to you than stew about it."],
      ["M", "That sounds ominous. Go on."],
      ["W", "In yesterday's meeting, when Ms. Alvarez asked who built the pricing model, you said \"we put it together\", and then you went through all the assumptions as though, well, as though you'd come up with them."],
      ["M", "Did I? I thought I was being inclusive. I did say \"we\"."],
      ["W", "You did, and that's what makes it tricky. \"We\" is true in the sense that you opened the file once to check the formatting. The cost curve and the sensitivity analysis, that was me, over three evenings."],
      ["M", "Okay. That's, um, fair, I suppose. I honestly didn't realize it came across like that."],
      ["W", "I believe you. I just don't want it to become the way things get remembered, with the intern reviews coming up in two weeks."],
      ["M", "Right. No, of course. What do you want me to do? I could email Ms. Alvarez and put it right."],
      ["W", "I'd rather you didn't make a big announcement. It would look as though I'd run to her. But if somebody asks again, you could just say, \"Hana built the model, I helped with the layout.\""],
      ["M", "Done. And I'll bring it up on Friday when we go over the numbers, casually, as if it were nothing."],
      ["W", "Thanks. Honestly, I was bracing for you to get defensive."],
      ["M", "I'm not that proud, I hope. Though I should have known better."]],
      qs: [
      { q: "Why does Hana want to speak to Joel?", o: ["To ask him to help her prepare for the intern reviews.","To ask him to check the assumptions in her sensitivity analysis.","To warn him that Ms. Alvarez is unhappy with the pricing model.","To raise a problem with how he described who built the model."], a: 3, x: "Elle lui reproche d'avoir présenté son travail comme collectif (« we ») devant Ms. Alvarez ; le modèle n'est pas critiqué." },
      { q: "What does Hana ask Joel to do?", o: ["Email Ms. Alvarez today to explain exactly how the work was divided.","Take responsibility for the layout so that she can focus on the analysis.","Say nothing more about the model until the intern reviews are finished.","Credit her properly from now on, without sending a formal correction."], a: 3, x: "Elle refuse une annonce officielle (« I'd rather you didn't make a big announcement ») mais veut que, si on lui pose la question, il la nomme." },
      { q: "What does Hana imply when she says \"we\" was true because Joel opened the file once?", o: ["He contributed far more to the project than he was willing to admit.","He deliberately lied to Ms. Alvarez about his work on the formatting.","His word was technically accurate but gave a misleading impression.","She regrets that she did not ask him for more help with the analysis."], a: 2, x: "Ironie : le mot est vrai au sens littéral (il a ouvert le fichier) mais trompeur sur l'essentiel. Hana croit à sa bonne foi, elle ne l'accuse pas de mentir." }
      ] },
    { id: "vzb007", diff: 2, ctx: "Listen to a conversation between two members of a student film society.", names: {W:"President",M:"Treasurer"}, lines: [
      ["W", "Okay, for the spring screening, I'm thinking of a Hitchcock double bill. The theater in the arts building holds two hundred, which should be plenty."],
      ["M", "I checked the budget, and we have six hundred dollars left. The license for each film is about two hundred and fifty. So two films would use almost everything."],
      ["W", "Hmm. What if we show one Hitchcock film and one short documentary? Documentaries are cheaper to license."],
      ["M", "That's possible. But will people come for a documentary? Last year, only fifteen people turned up for the documentary night."],
      ["W", "That's because it was on a Monday during exam week. A Friday evening would be much better."],
      ["M", "True. And we could charge two dollars at the door. If a hundred people come, that's two hundred dollars back."],
      ["W", "Charging at the door is against the student union rules unless we get a permit, and that takes two weeks."],
      ["M", "Then let's apply today. I'll also ask the film department if they can lend us a film for free."],
      ["W", "Great. I'll book the room for Friday the ninth."]],
      qs: [
      { q: "What are the speakers mainly discussing?", o: ["Which film the society should show next year.","How to organize and pay for the spring screening.","Why fewer students are attending the film society.","How to persuade the film department to join the society."], a: 1, x: "Ils choisissent le programme, la date et le financement de la séance de printemps." },
      { q: "Why did few people attend last year's documentary night?", o: ["It took place on a Monday during exam week.","The documentary was too short for a full evening.","The theater in the arts building was too small.","Tickets were too expensive for most students."], a: 0, x: "« it was on a Monday during exam week ». Le prix des billets n'est pas le problème : l'an dernier, l'entrée n'était pas payante." },
      { q: "What does the man suggest about showing two Hitchcock films?", o: ["It would use up nearly all of the money left.","It would be more popular than a documentary.","It would require a permit from the student union.","It would be possible only in a larger theater."], a: 0, x: "Deux licences à 250 dollars sur un budget de 600 : « almost everything ». Le permis concerne les billets, pas le nombre de films." }
      ] },
    { id: "vzb008", diff: 3, ctx: "Listen to a conversation between a student and an insurance adviser.", names: {W:"Adviser",M:"Student"}, lines: [
      ["M", "Hi, I submitted a claim last week for my bike, which was stolen from outside the library. I got a letter saying it was declined, and I don't understand why."],
      ["W", "Let me pull up your file. Okay. The policy covers theft of a bicycle only if it was secured with an approved lock, and the claim form says you used a cable lock."],
      ["M", "Yes, a cable lock. It came with the bike."],
      ["W", "The policy requires a D-lock or a chain with a certified rating. Cable locks can be cut in seconds, so insurers don't accept them."],
      ["M", "But nobody told me that when I signed up. I never saw that clause."],
      ["W", "It's on page six of the terms. I know, nobody reads page six. In fairness, it was also in the summary email we sent you."],
      ["M", "Okay, but the sales agent told me, and I remember this clearly, that bikes are covered anywhere in the city. Doesn't that count for something?"],
      ["W", "What a sales agent says over the phone isn't binding, I'm afraid. But if you can show me where that was stated in writing, it could be the basis for a complaint."],
      ["M", "I took a screenshot of the web page at the time. It says \"full cover wherever you park\"."],
      ["W", "Then I'd file a formal appeal, attach the screenshot, and keep the cable lock. I can't promise anything, but a decision based on misleading information is the sort of thing a review team looks at closely."]],
      qs: [
      { q: "Why was the student's claim declined?", o: ["The bike was stolen from a place the policy does not cover.","The lock he used did not meet the policy's requirements.","He reported the theft after the deadline set in the terms.","He had not paid the most recent premium on his policy."], a: 1, x: "Le contrat exige un antivol D-lock ou une chaîne certifiée ; un câble n'est pas accepté. Le lieu n'est pas en cause (c'est justement son argument)." },
      { q: "What does the adviser recommend the student do?", o: ["Ask the sales agent to confirm the offer in writing this week.","Buy a certified lock and apply for a completely new policy.","File a formal appeal supported by the web page he saved.","Wait until the review team decides to contact him directly."], a: 2, x: "« I'd file a formal appeal, attach the screenshot, and keep the cable lock ». La parole du vendeur n'engage pas, mais l'écrit peut servir." },
      { q: "What does the adviser imply by saying \"nobody reads page six\"?", o: ["The company hides its important clauses in the least visible places.","The student should have read the whole contract more carefully.","The clause about locks is not strictly enforced in everyday practice.","The clause is easily overlooked, but the company did inform him."], a: 3, x: "Elle reconnaît que personne ne lit cette page, tout en rappelant que l'information figurait aussi dans l'e-mail : empathie, mais la position de l'assureur reste la même." }
      ] },
    { id: "vzb009", diff: 4, ctx: "Listen to a conversation between two members of a debating society.", names: {W:"Woman",M:"Man"}, lines: [
      ["M", "So the committee voted. Seven to five, we're inviting him."],
      ["W", "Right, I heard. And I'm sure the vote was conducted with great decorum."],
      ["M", "Come on. You don't think a debating society should hear from someone it disagrees with?"],
      ["W", "I'm not saying it shouldn't hear him. I'm saying a podium and a seat in the audience are different things. An invitation confers a kind of legitimacy."],
      ["M", "Or it gives us the opportunity to take his arguments apart in public. That's what we do, remember? That's the whole point of the club."],
      ["W", "In theory. In practice, he gets forty minutes uninterrupted, and a few of our members get ninety seconds each at the microphone. That's not a debate. It's a broadcast with a feedback box."],
      ["M", "Then change the format. Give him twenty minutes and put someone who really knows the subject opposite him."],
      ["W", "Now that, I could get behind. If it were a real exchange, I'd even volunteer to be the opposition."],
      ["M", "You'd be brilliant. Honestly, it's what I was hoping you'd say."],
      ["W", "Well, don't flatter me. I haven't withdrawn my objection to the invitation. I've just identified the conditions under which I'd stop writing angry emails about it."]],
      qs: [
      { q: "What are the speakers mainly discussing?", o: ["Whether the committee followed the correct procedure when it voted.","How to recruit new members who disagree with the society's views.","Which of the society's members should speak against the guest first.","Whether and how the society should host a controversial speaker."], a: 3, x: "Il s'agit de savoir s'il faut inviter l'orateur et sous quelle forme ; la procédure de vote n'est évoquée que par ironie (« great decorum »)." },
      { q: "What does the woman mean by \"a broadcast with a feedback box\"?", o: ["The audience would have almost no chance to respond properly.","The event would be recorded and then shared widely on social media.","The speaker would only answer written questions after his long talk.","The members would be asked to rate the speaker's performance afterwards."], a: 0, x: "Métaphore : le public ne peut réagir que très brièvement (90 secondes). Ce n'est pas une critique de la diffusion mais de l'absence d'échange réel." },
      { q: "How does the woman's position change during the conversation?", o: ["She now accepts the invitation and drops all of her earlier objections to it.","She still objects to the invitation but would join if the format changed.","She agrees to withdraw her objection if the committee votes on it again.","She stays completely opposed and refuses to take any part in the event."], a: 1, x: "Elle maintient son objection (« I haven't withdrawn ») tout en posant une condition : un vrai débat, auquel elle serait prête à participer." }
      ] },
    { id: "vzb010", diff: 2, ctx: "Listen to a conversation between a student and the manager of a restaurant where he works.", names: {W:"Manager",M:"Student"}, lines: [
      ["M", "Mrs. Collins, do you have a minute? I wanted to talk about next month's schedule."],
      ["W", "Sure. Is there a problem?"],
      ["M", "My finals start on the fourth, and I've been scheduled for closing shifts on the third, the fifth, and the seventh. Closing means I don't get home until after midnight."],
      ["W", "Hmm. I see. We're short on staff in December, you know, with all the holiday parties."],
      ["M", "I know, and I don't want to leave you in a difficult position. I'd be happy to work the lunch shifts instead. They finish at three, so I'd still have the evenings to study."],
      ["W", "We already have two people on lunch, and it's usually quiet."],
      ["M", "I could also work the weekend of the tenth, after my exams, and take extra hours in the second half of the month."],
      ["W", "Now that's a deal. If you cover both Saturday and Sunday evenings on the tenth, I'll give your closing shifts to Adam. He needs the hours."],
      ["M", "That would be perfect. Thank you for being so understanding."],
      ["W", "Just do well on your exams. And send me your finals timetable so I can plan around it."]],
      qs: [
      { q: "Why does the student talk to the manager?", o: ["To request a higher rate of pay for the busy holiday period.","To explain why he will not be able to work at all in December.","To ask for a different schedule while his exams take place.","To complain that closing shifts are not shared fairly among staff."], a: 2, x: "Il demande de changer ses horaires de fermeture autour de ses examens. Il ne refuse pas de travailler en décembre : il propose d'autres créneaux." },
      { q: "What does the student offer to do?", o: ["Work all the closing shifts in the second half of the month.","Train Adam to take over his closing shifts.","Work lunch shifts now and extra hours after his exams.","Find another student to replace him on the third."], a: 2, x: "Il propose les services du midi et, après les examens, le week-end du 10 et des heures supplémentaires." },
      { q: "What does the manager imply when she says Adam \"needs the hours\"?", o: ["Adam has complained to her that he is not working enough hours.","Adam is not as reliable as the student, so he gets the late shifts.","Adam will take over the student's job permanently next year.","Adam will probably be glad to take the closing shifts."], a: 3, x: "Elle justifie son choix de lui donner ces services : il en a besoin, donc la solution arrange tout le monde." }
      ] },
    { id: "vzb011", diff: 3, ctx: "Listen to a conversation between two interns at a logistics company.", names: {W:"Woman",M:"Man"}, lines: [
      ["W", "Have you got a minute? I think I've found a mistake in the shipping cost sheet I sent to Mr. Park on Monday."],
      ["M", "How bad is it?"],
      ["W", "The formula for the fuel surcharge was pulling from the wrong column, so every route from the northern depot is underestimated by about eight percent. It's not catastrophic, but the total is off by roughly twelve thousand."],
      ["M", "Twelve thousand. Okay. And is he using it for the budget meeting?"],
      ["W", "That's Thursday. So I could just correct the file and send the new version without comment. Nobody would notice."],
      ["M", "He might, if he's already copied numbers into his slides. And honestly, I think you'd regret it. If he finds out you changed it silently, it looks as if you were hoping he wouldn't."],
      ["W", "But if I flag it, he'll know I made a mistake."],
      ["M", "He'll know you made a mistake and caught it before it mattered. That's the version of the story you want. Errors that get caught early are forgivable. Errors that get hidden turn into a personality trait."],
      ["W", "Ha. Okay. So an email, today, explaining what happened, with the corrected file attached."],
      ["M", "And put the corrected total in the first line, so he doesn't have to hunt for it."],
      ["W", "You're right. I'm just nervous about the intern review."]],
      qs: [
      { q: "What decision does the woman need to make?", o: ["Whether to redo the spreadsheet or ask the man to check it.","Whether to tell her supervisor about the error or quietly fix it.","Whether to present the figures herself at the budget meeting.","Whether to report the northern depot's costs to the regional manager."], a: 1, x: "Elle hésite entre corriger en silence et signaler l'erreur ; le reste du dialogue en découle." },
      { q: "Why is the timing of the correction important?", o: ["Mr. Park may use the figures at a meeting on Thursday.","The northern depot will change its fuel prices on Thursday.","The company will pay the surcharge before the end of the week.","The interns will be assessed on Thursday for their accuracy."], a: 0, x: "« That's Thursday » : la réunion budgétaire où les chiffres risquent d'être utilisés. Le bilan des stagiaires est une inquiétude lointaine, non datée." },
      { q: "What does the man mean by \"errors that get hidden turn into a personality trait\"?", o: ["People who make this kind of mistake usually have difficult personalities.","Hidden errors tend to be repeated by the same person again and again.","A supervisor will forgive almost any mistake that is admitted at once.","Hiding a mistake says more about your character than the mistake does."], a: 3, x: "Formule ironique : une erreur cachée n'est plus un simple accident, elle devient une marque de caractère. Il ne dit pas que tout aveu est pardonné." }
      ] },
    { id: "vzb012", diff: 4, ctx: "Listen to a conversation between two old friends at a reunion.", names: {W:"Woman",M:"Man"}, lines: [
      ["W", "So I hear you turned down Halvorsen and Pike. Please tell me it's because you're starting your own empire."],
      ["M", "Not an empire. I just didn't see myself on the eleventh floor of a glass tower in March, billing in six-minute increments."],
      ["W", "That's a very specific vision for someone who \"didn't see himself\" there."],
      ["M", "Okay, I may have seen it a little too clearly. Dad's been at a firm like that for twenty-six years. Dinner conversation is basically a case study in what happens next."],
      ["W", "And what does happen next?"],
      ["M", "Nothing bad, that's the thing. Good salary, a pension, a cardigan with the firm's logo. It's just that at his retirement party, the best thing anyone could find to say was that he never missed a deadline."],
      ["W", "Ouch. And how did he take your decision?"],
      ["M", "He said \"it's your life,\" in the voice that means precisely the opposite. Mom has been sending me job ads ever since, like little lifebuoys."],
      ["W", "So what's the plan? Or is \"not the glass tower\" the plan?"],
      ["M", "It's more of a starting position. I have an interview next week with a small development nonprofit. The pay is half of what Halvorsen offered."],
      ["W", "Half. And you're calling that a starting position."],
      ["M", "I'm calling it a bet. On being able to say something better at my own retirement party than \"never missed a deadline.\""]],
      qs: [
      { q: "What are the speakers mainly discussing?", o: ["How the man can eventually earn more money than his father ever did.","Why the man refused a job at a large firm and what he plans to do.","Which of the man's relatives gave him the best advice about his career.","Whether the woman should accept a job offer from the same law firm."], a: 1, x: "Le dialogue porte sur le refus de l'offre de Halvorsen and Pike et sur la piste alternative (une ONG). Le père est un élément du contexte, pas le sujet." },
      { q: "What troubles the man about his father's career?", o: ["What people chose to say about it at his retirement party.","How little time his father was able to spend with the family.","The low pension that his father finally received from the firm.","The way his father was treated by his colleagues at the end."], a: 0, x: "La seule chose que l'on ait trouvé à dire : « he never missed a deadline ». Le salaire et la retraite sont décrits comme corrects." },
      { q: "What does the man imply by saying his father said \"it's your life\" in a certain voice?", o: ["His father is proud of his independence.","His father has not understood the choice.","His father disapproves of the decision.","His father is leaving the decision to his mother."], a: 2, x: "Il précise que le ton signifie « exactement le contraire » de la phrase : le père désapprouve. Ce n'est pas de l'incompréhension." }
      ] },
    { id: "vzb013", diff: 3, ctx: "Listen to a conversation between a student and a bank adviser.", names: {W:"Adviser",M:"Student"}, lines: [
      ["M", "I got this letter saying I'm pre-approved for a student credit card. It says \"zero percent interest on purchases,\" and that sounds almost too good to be true."],
      ["W", "Let me see. Ah, yes. The zero percent is an introductory rate. It applies for the first twelve months, and then it goes up to twenty-four point nine percent APR."],
      ["M", "Twenty-five percent? That's brutal. But I can just pay everything off before the twelve months are up, right?"],
      ["W", "You can, and many people do. The risk is for those who don't. Interest then applies to the whole outstanding balance, so a small amount left in month thirteen can still cost you."],
      ["M", "Hmm. What about the annual fee? I saw something about thirty-five dollars."],
      ["W", "It's waived the first year. After that it's thirty-five, unless you spend more than two thousand dollars a year, in which case it's waived again."],
      ["M", "I doubt I'd spend two thousand. Maybe fifteen hundred."],
      ["W", "Then the real cost of the card in year two is that fee, which you could see as the price of building a credit history. If that's your only aim, a secured card might do more for you at lower cost."],
      ["M", "What's a secured card?"],
      ["W", "You deposit, say, three hundred dollars, and that becomes your limit. You can't overspend, and your payments are still reported to the credit agencies."],
      ["M", "That sounds safer. Could I switch to a regular card later?"],
      ["W", "After twelve months of on-time payments, usually yes."]],
      qs: [
      { q: "Why does the student talk to the adviser?", o: ["To dispute an interest charge that appeared on his current card.","To understand the terms of a credit card offer he received.","To ask for a higher spending limit on his existing credit card.","To apply for a loan to cover the tuition fees of his first year."], a: 1, x: "Il montre sa lettre de pré-approbation et pose des questions sur le taux, les frais et le fonctionnement de la carte." },
      { q: "According to the adviser, what happens if a balance remains after the first year?", o: ["The annual fee is charged retroactively for the first year.","The card is automatically converted into a secured card.","Only the part above two thousand dollars is charged interest.","The high rate is applied to the entire amount still owed."], a: 3, x: "« Interest then applies to the whole outstanding balance ». Le seuil de 2 000 dollars concerne les frais annuels, pas les intérêts." },
      { q: "Why does the adviser mention a secured card?", o: ["It carries a lower interest rate than any other card a student can get.","It is the only kind of card that the student qualifies for at present.","It could build a credit history more cheaply and with less overspending.","It lets the student avoid having his payments reported to credit agencies."], a: 2, x: "Si l'objectif est seulement de construire un historique de crédit, la carte garantie coûte moins et empêche de dépenser plus que le dépôt." }
      ] },
    { id: "vzb014", diff: 3, ctx: "Listen to a conversation between two friends planning a weekend trip.", names: {W:"Woman",M:"Man"}, lines: [
      ["W", "I've been comparing options for Edinburgh. The train is ninety pounds return. The coach is thirty-two."],
      ["M", "Thirty-two! That's a no-brainer, surely."],
      ["W", "It takes nine hours each way, though. The train takes four and a half. And you'll remember I have that seminar at nine on Monday."],
      ["M", "Right. But if we take the night coach back on Sunday, we'd get in at six, and you could still go home, shower, and make it."],
      ["W", "Technically. I'd be in the seminar the way a ghost is in a house."],
      ["M", "Fine. Mixed option, then: train there on Friday, coach back on Sunday night. That's about sixty-one."],
      ["W", "Sixty-one. Hold on, though. I found an advance fare: seventy pounds return on the train if we book at least two weeks ahead, and we're three weeks out."],
      ["M", "Seventy against sixty-one. For nine pounds, I'd rather not spend Sunday night upright on a coach. What's the catch?"],
      ["W", "Advance tickets can't be refunded."],
      ["M", "Which matters, given our record with trips that get cancelled."],
      ["W", "Exactly. But if we do go, it's the cheapest way of doing it without wrecking Monday."],
      ["M", "Fine. Book it before I change my mind."]],
      qs: [
      { q: "What are the speakers mainly discussing?", o: ["How to travel to Edinburgh, balancing cost against time and comfort.","Whether to cancel the whole trip because of the high cost of the train.","How to get back from Edinburgh in time for a seminar on Monday morning.","Which of the two of them should pay for the advance train tickets first."], a: 0, x: "Ils comparent train, car et formule mixte en pesant prix, durée et fatigue ; le retour du lundi n'est qu'un des arguments." },
      { q: "What is the disadvantage of the advance train fare?", o: ["The tickets have to be bought at least three weeks in advance.","The fare is only available to students with a valid railcard.","The train must be taken at a very early hour on Friday morning.","The tickets cannot be refunded if the trip is cancelled."], a: 3, x: "« Advance tickets can't be refunded », ce qui compte vu leur passé de voyages annulés. Le prix est supérieur de neuf livres mais ce n'est pas présenté comme l'inconvénient du billet." },
      { q: "What does the woman mean when she says she would be in the seminar \"the way a ghost is in a house\"?", o: ["She would arrive late and disturb all of the other students.","She would be afraid of speaking in front of the whole class.","She would be present but too tired to take part properly.","She would have to leave the seminar early to go home to bed."], a: 2, x: "Comparaison humoristique : présente physiquement, mais sans réellement être là, après une nuit dans le car." }
      ] },
    { id: "vzb015", diff: 4, ctx: "Listen to a conversation between the chair and the treasurer of a student theater society.", names: {W:"Chair",M:"Treasurer"}, lines: [
      ["M", "I've got the revised figures from the union, and, well, it isn't pretty. They've cut our grant by forty percent."],
      ["W", "Forty. That's, what, not even enough to cover the venue for the autumn showcase."],
      ["M", "Roughly. Though I'd gently point out that in June, when I asked whether we should diversify our income, the answer was that sponsorship was a distraction."],
      ["W", "I said it was a distraction from the creative work. I didn't say never."],
      ["M", "Right. \"Not now\" and \"never\" being, in practice, the same sentence if you say it often enough."],
      ["W", "Okay. I deserve that. What are our options?"],
      ["M", "Three. Cut the showcase to one night, charge for tickets, which the union may or may not approve, or ask the alumni network. I'd lean toward the alumni, because they're the people who'd most like to see us survive."],
      ["W", "Asking alumni feels like begging, to be honest."],
      ["M", "It feels like begging when you ask for charity. If you invite them to back something they once loved, it feels more like an invitation."],
      ["W", "That's a good line. Did you rehearse that?"],
      ["M", "Since June, actually."],
      ["W", "Fine. You write the letter, I'll sign it, and we'll tell the members on Thursday before they hear it from someone else."]],
      qs: [
      { q: "What is the main issue the speakers are dealing with?", o: ["How to respond to a large cut in their funding.","How to choose a venue for the autumn showcase.","Whether the union treated the society unfairly.","How to find new members for the society."], a: 0, x: "Le dialogue part de la coupe de 40 % de la subvention et cherche des solutions ; le lieu en est une conséquence, pas le sujet." },
      { q: "What does the treasurer imply by mentioning his question in June?", o: ["He had warned the union about the cut well before it happened.","The chair earlier rejected an idea that would have helped now.","He once asked the chair to resign as head of the theater society.","The society's main sponsors had stopped giving it money in June."], a: 1, x: "Il rappelle poliment que sa proposition de diversifier les revenus avait été écartée ; la phrase sur « not now » et « never » est une critique ironique." },
      { q: "How does the treasurer suggest the alumni should be approached?", o: ["As former members who feel they are obliged to repay the society.","As donors who would in return be given a share of ticket sales.","As people offered a chance to support something they valued.","As a group who should first be asked for their opinion on the plan."], a: 2, x: "Il oppose la charité à une invitation à soutenir quelque chose qu'ils ont aimé. Les billets et l'obligation morale ne sont pas évoqués ainsi." }
      ] },
    { id: "vzb016", diff: 3, ctx: "Listen to a conversation between a customer and an employee of a mobile phone company.", names: {W:"Employee",M:"Customer"}, lines: [
      ["M", "Hi, I'd like to cancel my contract, please. I'm moving back home next month."],
      ["W", "I'm sorry to hear that. May I ask what's behind the decision? Is it the price, or the coverage?"],
      ["M", "Neither, really. I'm leaving the country, so I won't be able to use the plan."],
      ["W", "Understood. Before I process it, I should mention that we can suspend a contract for up to six months, free of charge, if you're only away temporarily."],
      ["M", "It isn't temporary. I'm finishing my degree and going back for good."],
      ["W", "All right. Then the cancellation is straightforward, but there's an early termination fee. You're at month fourteen of a twenty-four-month contract, so it's the remaining ten months at half the monthly rate."],
      ["M", "Half of twenty-eight, times ten. A hundred and forty pounds for a plan I won't be able to use."],
      ["W", "I can see that's frustrating. One option is to transfer the contract to someone else. If a friend takes it over, there's no fee at all."],
      ["M", "A transfer? My flatmate's phone just broke, actually. She might want it."],
      ["W", "Then she'd need to pass a credit check and come in with ID. It takes about twenty minutes."],
      ["M", "That's much better. Can I bring her tomorrow?"],
      ["W", "Of course. I'll make a note on your file so that nobody processes the cancellation in the meantime."]],
      qs: [
      { q: "What is the main purpose of the conversation?", o: ["The man wants to change to a cheaper plan with the same coverage.","The man wants to complain about poor service from the company.","The man wants to suspend his contract while he is abroad.","The man wants to end his contract and learns how to avoid a fee."], a: 3, x: "Il veut résilier et découvre que le transfert supprime les frais de 140 livres. La suspension est proposée mais ne convient pas." },
      { q: "Why is suspending the contract not a suitable option?", o: ["The man is leaving the country permanently.","Suspension would still require him to pay the monthly rate.","Suspension is only possible during the first year of a contract.","The man's contract has too many months left to run."], a: 0, x: "« It isn't temporary... going back for good ». La suspension concerne seulement les absences temporaires." },
      { q: "What will the man most likely do next?", o: ["Pay the early termination fee and cancel the contract immediately.","Return with his flatmate so that she can take over the contract.","Ask the company to lower the fee because his own phone is broken.","Wait until next month to cancel the contract in person at the store."], a: 1, x: "Il demande s'il peut revenir le lendemain avec sa colocataire ; elle devra passer un contrôle de crédit et présenter une pièce d'identité." }
      ] },
    { id: "vzb017", diff: 4, ctx: "Listen to a conversation between two students who are reviewing each other's essays.", names: {W:"Woman",M:"Man"}, lines: [
      ["W", "Okay, I've read your draft, and before I say anything, I want it on the record that I like your argument."],
      ["M", "That's the preamble to a demolition, isn't it?"],
      ["W", "It's the preamble to an honest comment. Your argument is that remote work reduces innovation. Fine. But your evidence is one study, and it's a study of one company."],
      ["M", "A big company. Forty thousand employees."],
      ["W", "Size isn't diversity. And you cite it three times as though it were three studies. I counted."],
      ["M", "I was reinforcing the point."],
      ["W", "You were repeating the point. Reinforcing would be bringing in something that comes from a different direction."],
      ["M", "Okay, that stings a bit. But in my defense, the limit is eighteen hundred words and I'm already at seventeen-ninety."],
      ["W", "Then cut the second paragraph. It's a nice story about your uncle's office, but it isn't evidence. It's atmosphere."],
      ["M", "I like the uncle."],
      ["W", "Everyone likes the uncle. That's the problem. He's been charming you out of rigor."],
      ["M", "Fine. The uncle goes and a second source goes in. Can I return the favor? Your conclusion says that, and I quote, \"all things considered, the matter remains complex.\" So does a tax return. It doesn't tell me anything."],
      ["W", "Touché."]],
      qs: [
      { q: "What are the speakers mainly doing?", o: ["Giving each other critical feedback on their written work.","Preparing a joint presentation on remote work for their course.","Arguing about whether remote work really harms innovation at firms.","Deciding which of their two essays is the stronger one to submit."], a: 0, x: "Chacun relit l'essai de l'autre (« Can I return the favor? »). Le sujet du travail à distance n'est qu'un contenu." },
      { q: "What does the woman criticize about the way the man uses the study?", o: ["He misreports the number of employees who were involved in it.","He cites it repeatedly, which suggests he has several sources.","He quotes the study's main results inaccurately in his second paragraph.","He never names the company in which the study was carried out."], a: 1, x: "« you cite it three times as though it were three studies » : la répétition donne l'illusion de sources multiples. La taille de l'entreprise n'est pas ce qu'elle reproche en dernier." },
      { q: "What is the man's objection to the woman's conclusion?", o: ["It contradicts the evidence presented earlier in her essay.","It is too long for the word limit set by the course.","It is so vague that it says nothing of substance.","It repeats a point that she had already made twice."], a: 2, x: "La comparaison avec une déclaration d'impôts : complexe mais sans contenu. Il lui reproche une conclusion creuse." }
      ] },
    { id: "vzb018", diff: 2, ctx: "Listen to a conversation between two coworkers.", names: {W:"Woman",M:"Man"}, lines: [
      ["W", "Have you heard that Gabriela's last day is the twentieth?"],
      ["M", "Yes. I was thinking we should do something for her. She's been here for six years."],
      ["W", "Me too. A surprise lunch? Maybe at that Thai place she likes."],
      ["M", "A lunch could work, but the restaurant only takes group reservations for eight or more, and there are twenty of us."],
      ["W", "Twenty would be fine, actually. They'd give us the back room. But she'd notice if we all left the office at the same time."],
      ["M", "What if we tell her the manager is taking her out for a goodbye meeting? Then we all show up."],
      ["W", "She'd guess. She's very sharp. Let's ask Mr. Ford to say there's a client lunch and she's expected to attend."],
      ["M", "Better. And a gift? I'd like something personal, not a gift card."],
      ["W", "She loves gardening. We could give her a book about gardens around the world, and everyone signs it."],
      ["M", "Perfect. I'll message the group and ask for ten dollars each."],
      ["W", "And please tell them not to mention it in the group chat she's part of, or the surprise will be spoiled."]],
      qs: [
      { q: "What are the speakers mainly doing?", o: ["Choosing a restaurant for a team meeting.","Organizing a client lunch with their manager.","Collecting money for a retirement present.","Planning a surprise farewell for a colleague."], a: 3, x: "Ils organisent un déjeuner surprise pour le départ de Gabriela. Le « client lunch » n'est qu'un prétexte." },
      { q: "How will they get Gabriela to the restaurant?", o: ["By saying that the manager wants to take her out for lunch alone.","By telling her that she must attend a lunch with a client.","By inviting her to a meeting about choosing the Thai restaurant.","By asking her to help choose the gift for the rest of the team."], a: 1, x: "Mr. Ford dira qu'il y a un déjeuner client auquel elle doit assister : l'idée du « goodbye meeting » est rejetée car elle devinerait." },
      { q: "Why does the woman warn the man about the group chat?", o: ["Too many people would answer at once and cause confusion.","The manager does not allow messages about gifts in the chat.","The restaurant might see the message and cancel the booking.","Gabriela is a member of it and might read the plans."], a: 3, x: "« the group chat she's part of » : Gabriela ferait échouer la surprise en lisant le message." }
      ] },
    { id: "vzb019", diff: 3, ctx: "Listen to a conversation between a team leader and an employee at a customer service center.", names: {W:"Team leader",M:"Employee"}, lines: [
      ["W", "Thanks for coming in, Daniel. I'd like to go over your numbers from last month. Overall, they're good. Your customer satisfaction score is ninety-two percent, which is the best on the team."],
      ["M", "Great. But I sense a \"but.\""],
      ["W", "A small one. Your average call time is eleven minutes, and the team target is seven. You spend a lot of time with each customer."],
      ["M", "I know. But I find that if I rush, people call back the next day with the same problem. A longer call now saves a second one later."],
      ["W", "That's a fair argument, and the data supports it. Your repeat-call rate is the lowest, too. The trouble is that management looks at calls per hour, and the dashboard doesn't show repeat calls."],
      ["M", "So I'm being penalized for doing the job properly."],
      ["W", "Not penalized, but you're flagged. Two more months below target and the regional manager will want a conversation."],
      ["M", "What can I do?"],
      ["W", "Two things. First, let me take your repeat-call figures to the regional manager as an argument for changing the metric. Second, on the simple calls, like password resets, try to move faster, so you have the time to be thorough on the complicated ones."],
      ["M", "That's reasonable. I hadn't thought of splitting it that way."],
      ["W", "It's not a fix, just a bridge."]],
      qs: [
      { q: "What is the main purpose of the meeting?", o: ["To announce that the employee will soon be promoted to team leader.","To warn the employee that he is in danger of losing his job.","To review the employee's performance and raise one concern.","To explain why the call-time target has recently been changed."], a: 2, x: "La responsable commence par les bons résultats, puis aborde la durée des appels. Il y a une alerte, pas un avertissement de licenciement." },
      { q: "Why does the employee spend so long on each call?", o: ["He wants to solve the problem so that customers do not call again.","He is worried that his satisfaction score will fall if he hurries.","He has been given the most complicated cases on the whole team.","He is not familiar with the dashboard that monitors his call times."], a: 0, x: "« if I rush, people call back the next day with the same problem ». Le taux de rappel confirme son raisonnement." },
      { q: "What does the team leader mean by \"It's not a fix, just a bridge\"?", o: ["Her advice only applies to the simple calls such as password resets.","Her advice only helps until the way performance is measured changes.","The regional manager has already agreed to change the target.","The employee will have to adopt a new way of working permanently."], a: 1, x: "Un « pont » est une solution provisoire pour tenir pendant qu'on tente de modifier l'indicateur. Elle ne promet pas encore le changement." }
      ] },
    { id: "vzb020", diff: 4, ctx: "Listen to a conversation between two friends.", names: {W:"Woman",M:"Man"}, lines: [
      ["W", "So it's official? You're deferring the master's?"],
      ["M", "Official-ish. I emailed the admissions office, and they said I can defer for one year, provided I don't take a degree anywhere else."],
      ["W", "And what will you do with your year? Besides, I imagine, discovering yourself in some inexpensive country."],
      ["M", "Actually, I got a job. At a logistics firm in Rotterdam. Junior analyst. Nothing glamorous."],
      ["W", "A gap year with a pension plan. How very sensible of you. I'd assumed there would be at least one trek involved."],
      ["M", "There might be. On weekends. Honestly, I got to the end of my undergrad and realized I had no idea what any of this looks like outside a classroom. I'm about to pay forty thousand to learn finance. I'd quite like to know what I'm learning it for."],
      ["W", "That's the first time anyone's made a gap year sound like due diligence."],
      ["M", "Well, I'm cheaper than a consultant."],
      ["W", "And the risk? That you like the job so much you never go back?"],
      ["M", "Or that I hate it, and find out for the price of a year's salary rather than a year's tuition. Either answer is worth having."],
      ["W", "Hm. I'll say this. It's less of a leap than I would have given you credit for. I think I'm a bit envious."],
      ["M", "You could always call it a strategic pause."],
      ["W", "No. I'll stick with envious."]],
      qs: [
      { q: "Why does the man want to defer his master's program?", o: ["To earn enough money to pay for the cost of the master's program.","To travel and discover what he wants to study at university.","To take a degree at a different university in the Netherlands.","To learn what the work is like before paying for the degree."], a: 3, x: "Il veut savoir à quoi serviront ses études avant de payer 40 000 : « I'd quite like to know what I'm learning it for »." },
      { q: "What does the woman mean by \"a gap year with a pension plan\"?", o: ["She teases him because his plan is more conventional than most gap years.","She is impressed that his future employer offers such generous benefits.","She seriously criticizes him for giving up his studies in order to work.","She doubts that he will really return to the university at the end."], a: 0, x: "Ironie : une année sabbatique avec un plan de retraite, c'est l'opposé du voyage aventureux attendu. Elle taquine, sans le critiquer sérieusement." },
      { q: "What does the man see as an advantage of his plan?", o: ["He will be able to apply for a much better master's program next year.","He will gain contacts that would guarantee him a job after his degree.","He can test whether the career suits him more cheaply than a degree.","He will be able to use the weekends to travel around northern Europe."], a: 2, x: "« find out for the price of a year's salary rather than a year's tuition » : il teste le métier à moindre coût, que l'expérience le confirme ou non." }
      ] },
    { id: "vzb021", diff: 3, ctx: "Listen to a conversation between a student and a volunteer coordinator at a food bank.", names: {W:"Coordinator",M:"Student"}, lines: [
      ["M", "Hi, I signed up to volunteer here, and I got an email saying to check in with you before my first shift."],
      ["W", "Yes, welcome, and thanks for coming in. Can I ask what drew you to us? Some people are doing hours for a course requirement, others just want to help."],
      ["M", "A bit of both, honestly. My business ethics course needs thirty hours of community service. But I'd have wanted to do something like this anyway."],
      ["W", "That's fine, nothing wrong with that. We just need to know, because course volunteers need a signed form at the end. I'll give it to you after your last shift. Don't lose it, because I can't replace it."],
      ["M", "Understood. What would I be doing?"],
      ["W", "Saturday mornings you'd be at the sorting station, checking dates and packing boxes. Later, if you're reliable, we sometimes ask people to help at the front desk, talking with clients as they come in."],
      ["M", "I'd actually prefer the front desk. I speak Spanish, and I heard a lot of your clients do."],
      ["W", "Really? That would be very valuable. But we like new volunteers to do a month of sorting first. It isn't a test. It's so you understand how the whole operation works, which makes you better at the desk."],
      ["M", "That makes sense. Is there anything I should know about the clients?"],
      ["W", "Mainly, treat everyone as you'd treat a customer at your favorite store. And no questions about why they're here. People get enough of that elsewhere."]],
      qs: [
      { q: "What is the purpose of the meeting?", o: ["To prepare the student for his work as a volunteer.","To interview the student for a paid position.","To arrange a food donation from the student's course.","To ask the student to translate documents into Spanish."], a: 0, x: "Il vient faire le point avant son premier service : présentation, tâches, règles de conduite." },
      { q: "Why does the coordinator tell the student not to lose the form?", o: ["It contains the schedule of all his Saturday shifts for the month.","It proves his hours to the course and cannot be replaced.","It gives him access to the front desk and the sorting station.","It lists the questions he is allowed to ask the clients."], a: 1, x: "Le formulaire signé prouve ses heures de service pour le cours ; « I can't replace it »." },
      { q: "Why does the coordinator want new volunteers to start with sorting?", o: ["Their reliability must be tested before they meet clients.","Sorting is the only task for which volunteers receive training.","There are too few staff to work at the front desk at weekends.","Understanding the whole operation helps them serve clients."], a: 3, x: "« It isn't a test. It's so you understand how the whole operation works ». Le piège « test » est expressément écarté." }
      ] },
    { id: "vzb022", diff: 3, ctx: "Listen to a conversation between a student and an employee at a fitness center.", names: {W:"Employee",M:"Student"}, lines: [
      ["M", "Hi, I need to freeze my membership. I'm having surgery next week, and my doctor says no exercise for two months."],
      ["W", "Sorry to hear that. I hope it goes well. We do offer freezes, but only with a medical certificate, and the minimum is one month."],
      ["M", "I can bring the certificate. Do I still pay during the freeze?"],
      ["W", "There's a flat fee of five pounds a month. That keeps your account active and your joining rate locked in."],
      ["M", "Locked in? What does that mean?"],
      ["W", "Your current rate is twenty-two pounds a month. If you cancelled and rejoined, the new rate would be thirty-four. During a freeze, you keep the old one."],
      ["M", "Then freezing is definitely better than cancelling. What happens at the end of the two months? Does it unfreeze automatically?"],
      ["W", "Yes, automatically. If you need longer, you have to extend it before the end date, in person or by email, otherwise billing restarts the next day."],
      ["M", "And if my recovery takes less than two months?"],
      ["W", "Then you can restart early. Just give us forty-eight hours' notice. You won't get a refund for the unused freeze fee, though."],
      ["M", "Fine. I'll bring the certificate tomorrow."]],
      qs: [
      { q: "What does the man want to do?", o: ["Cancel his membership completely and rejoin at a later date.","Change to a cheaper kind of membership during his recovery.","Suspend his membership while he recovers from surgery.","Get a refund for the months when he will not use the gym."], a: 2, x: "Il demande un « freeze » pour deux mois de convalescence ; il compare ensuite avec une résiliation." },
      { q: "Why is freezing better for the man than cancelling?", o: ["He would not have to pay anything during the freeze.","He would not need a medical certificate to restart.","He would keep a lower monthly rate when he returns.","He would be allowed to use the gym for one month."], a: 2, x: "Le tarif actuel de 22 livres est conservé, alors qu'une nouvelle inscription coûterait 34 livres. Le gel n'est pas gratuit (5 livres par mois)." },
      { q: "What must the man do if his recovery takes longer than two months?", o: ["Give forty-eight hours' notice before he restarts.","Ask for an extension before the freeze ends.","Bring a second medical certificate to the center.","Pay the monthly fee of twenty-two pounds in advance."], a: 1, x: "Sans prolongation demandée avant la date de fin, la facturation reprend le lendemain. Le préavis de 48 heures concerne une reprise anticipée." }
      ] },
    { id: "vzb023", diff: 4, ctx: "Listen to a conversation between two trainee auditors at an accounting firm.", names: {W:"Woman",M:"Man"}, lines: [
      ["M", "Please tell me the Delmar files came in overnight."],
      ["W", "Define \"came in.\" I received an email saying they're \"in the process of being retrieved from the archive.\" Which, in my experience, translates as \"we haven't started.\""],
      ["M", "It's Thursday. The sign-off is next Tuesday."],
      ["W", "I'm aware. And apparently their finance director is \"traveling until Monday.\" Conveniently."],
      ["M", "So either we go to Ms. Reyes now, or we sit on it and hope."],
      ["W", "I vote for going now. If we wait until Monday and nothing has arrived, it'll look as though we've been hiding the problem for four days."],
      ["M", "But if we escalate, it might look as though we can't manage a client. I've been told twice that she hates being the one who has to call clients."],
      ["W", "Maybe. But there's a difference between \"we can't manage them\" and \"we've documented that they're late, and here's what it does to the timeline.\" The first is a complaint. The second is information."],
      ["M", "That's neat. Could we also propose a fallback? Like, we start testing the invoices we do have, and flag the missing ones as outstanding?"],
      ["W", "Partial testing. Yes, that's good. It shows we're not just waiting around, and it keeps the Tuesday date alive, at least on paper."],
      ["M", "At least on paper. You've been here two months and you already sound like a partner."],
      ["W", "I'm choosing to take that as a compliment."]],
      qs: [
      { q: "What problem are the speakers facing?", o: ["A client has not supplied documents and a deadline is approaching.","A client has sent in documents that contain several serious errors.","Their manager has suddenly changed the date of the final sign-off.","The client's finance director has refused to approve the audit."], a: 0, x: "Les fichiers de Delmar n'arrivent pas alors que la validation est prévue mardi." },
      { q: "Why does the woman prefer to tell Ms. Reyes immediately?", o: ["Ms. Reyes has asked to be told about all late documents.","The client's finance director is likely to return on Monday.","Escalating early is the quickest way of obtaining the files.","Waiting could make it seem that they concealed the delay."], a: 3, x: "Si rien n'arrive lundi, on croira qu'ils ont caché le problème pendant quatre jours. L'idée d'accélérer les fichiers n'est pas avancée." },
      { q: "What distinction does the woman draw between a \"complaint\" and \"information\"?", o: ["Complaints are addressed to clients while information goes to managers.","Stating the facts and their effects is more professional than blaming.","Information should be given only after the documents have arrived.","A complaint is acceptable only when it is made in writing to a manager."], a: 1, x: "Même fait (le retard), deux présentations : se plaindre du client ou documenter son effet sur le calendrier. La seconde est neutre et utile." }
      ] },
    { id: "vzb024", diff: 3, ctx: "Listen to a conversation between a tenant and her landlord.", names: {W:"Tenant",M:"Landlord"}, lines: [
      ["W", "Mr. Dalton, it's been nine days since I first reported the radiator in the living room. It's still cold."],
      ["M", "Yes, yes, I have it written down. The thing is, the plumber we use for our buildings has been off sick."],
      ["W", "I understand that, but it's the end of November. And I have a baby. She's four months old."],
      ["M", "Of course, and I appreciate that. I'm not saying it isn't important."],
      ["W", "What I'd like is a date. Not \"soon\" or \"as soon as possible,\" but a day on which someone is actually coming."],
      ["M", "I can't promise a day, as I'm still waiting for the plumber's schedule. What I can do is bring you a portable heater this afternoon in the meantime."],
      ["W", "I'd be grateful for that. But a heater doesn't fix the radiator, and I'm also worried about the electricity bill."],
      ["M", "Hmm. I could take something off the rent. Say twenty pounds?"],
      ["W", "I'd rather discuss the rent after the radiator is fixed. A date by Friday, in writing, and the heater today. If there's no date by Friday, I'll ask the council's housing officer to inspect."],
      ["M", "There's no need to bring the council into this. I'll call another plumber tomorrow morning and email you by noon with a time."],
      ["W", "Thank you. That's all I wanted."]],
      qs: [
      { q: "Why is the tenant talking to the landlord?", o: ["To ask for a reduction in her rent for the winter.","To report that her baby has become ill.","To press him to get a broken radiator repaired.","To complain about the high cost of her electricity."], a: 2, x: "Elle réclame une date de réparation pour le radiateur, signalé depuis neuf jours." },
      { q: "What does the landlord offer immediately?", o: ["A portable heater that same afternoon.","A date on which the plumber will come.","A reduction of twenty pounds in the electricity bill.","The name of another plumber he trusts."], a: 0, x: "« bring you a portable heater this afternoon ». La baisse de loyer est évoquée, mais la locataire la refuse pour l'instant." },
      { q: "Why does the landlord change his position at the end of the conversation?", o: ["He has just received the plumber's schedule for the week.","He has realized that the tenant's baby is seriously ill.","He fears that she will stop paying her rent altogether.","He wants to avoid an inspection by the council."], a: 3, x: "Après la menace de l'inspection (« I'll ask the council's housing officer »), il propose aussitôt de trouver un autre plombier." }
      ] },
    { id: "vzb025", diff: 4, ctx: "Listen to a conversation between two friends who belong to a book club.", names: {W:"Woman",M:"Man"}, lines: [
      ["M", "You didn't finish it, did you? I can tell from your face."],
      ["W", "I finished it. I'd like it noted that finishing it was an act of will."],
      ["M", "Come on. It's sold eight million copies."],
      ["W", "So has a certain brand of ketchup. I'm not sure the number settles anything."],
      ["M", "But the writing is clean. It moves. You can't say you didn't want to find out what happened."],
      ["W", "I wanted to find out what happened for about ninety pages. After that I wanted to find out the way you want to find out the end of a long meeting. Look, the prose is perfectly competent. It's just competent in the same way on every page, as if the author had decided at the start what a sentence is."],
      ["M", "You make that sound like a flaw. Some people read to relax."],
      ["W", "And that's lovely, I'm not against relaxing. My complaint is that the book pretends to be about something. It has a theme, grief, apparently, with a capital G, but it handles it like a plot device."],
      ["M", "So you'd have preferred a book that makes you feel worse."],
      ["W", "I'd have preferred one that made me feel anything, rather than one that tells me what I should be feeling at each moment."],
      ["M", "Fine, I'll concede the grief point. But I'm still nominating it for the club, because half of the group will actually read it."],
      ["W", "Which is a perfectly good criterion. Just don't expect me to defend it on Thursday."]],
      qs: [
      { q: "What are the speakers mainly discussing?", o: ["The woman's negative opinion of a best-selling novel.","Which book the club should read at its next meeting.","The best way to write about the subject of grief.","Whether books that sell many copies are better written."], a: 0, x: "La conversation tourne autour de l'avis critique de la femme sur un roman à succès ; le choix du livre est abordé en fin d'échange seulement." },
      { q: "Why does the woman compare the book's sales to those of a brand of ketchup?", o: ["To say that the book is sold in too many stores.","To show that the novel is aimed at a mass audience.","To suggest that popularity does not prove quality.","To suggest that the book has been over-advertised."], a: 2, x: "Raisonnement : un grand nombre de ventes ne démontre rien sur la qualité (« I'm not sure the number settles anything »)." },
      { q: "What is the woman's main criticism of the way the book deals with grief?", o: ["It makes readers feel far worse than they would like to feel.","It treats the subject of grief too briefly in the first ninety pages.","It describes grief in language that is far too complicated.","It uses grief as a device and tells readers what to feel."], a: 3, x: "Elle reproche un traitement mécanique : le thème sert l'intrigue et dicte les émotions, au lieu de les faire naître." }
      ] },
    { id: "vzb026", diff: 3, ctx: "Listen to a conversation between a student and a post office clerk.", names: {W:"Clerk",M:"Student"}, lines: [
      ["M", "Hi. I got a card in my mailbox about a parcel, and it says I have to pay before it can be released. It's from my grandmother in Canada."],
      ["W", "Let me see. Yes, there are import charges of ninety-four pounds. Customs have assessed the contents."],
      ["M", "Ninety-four? It's just a winter coat and a few things for my birthday. She marked it as a gift."],
      ["W", "Gifts are treated more leniently, but only up to a certain value. The declared value on this form is two hundred and forty pounds, which is above the threshold."],
      ["M", "Two hundred and forty? That can't be right. The coat is secondhand. She told me she wrote that on the form."],
      ["W", "The form says \"wool coat, new.\" Perhaps the clerk at her post office filled it in incorrectly."],
      ["M", "Probably. Can it be corrected?"],
      ["W", "You can appeal. You'd need a statement from the sender with a receipt or an honest valuation, and you'd send it to customs within thirty days. But we only hold the parcel for fourteen days."],
      ["M", "And after that?"],
      ["W", "It's returned to Canada, at your grandmother's expense, unless you've paid or asked for an extension."],
      ["M", "Can I ask for an extension?"],
      ["W", "Yes. I can note a request on your file now, which gives you another seven days."],
      ["M", "Then I'll ask her for the receipt tonight, and come back on Monday."]],
      qs: [
      { q: "Why has the student come to the post office?", o: ["To send a parcel to his grandmother in Canada.","To find out why he must pay to receive a parcel.","To collect a gift that was delivered by mistake.","To ask customs to return a parcel to its sender."], a: 1, x: "Il a reçu un avis de paiement avant la remise du colis de sa grand-mère." },
      { q: "What caused the high import charge?", o: ["The coat was declared as new and was given a high value.","The parcel was not marked as a gift by the sender.","The post office clerk in Canada forgot to fill in the form.","The parcel contained more items than the sender declared."], a: 0, x: "Le formulaire dit « wool coat, new » avec une valeur de 240 livres, au-dessus du seuil des cadeaux. Le colis était bien marqué comme cadeau." },
      { q: "Why does the clerk offer to note a request on the student's file?", o: ["To tell customs straight away that the form was filled in incorrectly.","To give him time to get the evidence before the parcel goes back.","To make sure that the charges are cancelled as soon as possible.","To confirm that the parcel will be held at the post office for thirty days."], a: 1, x: "La demande de prolongation de sept jours lui laisse le temps de réunir le reçu avant le renvoi du colis (délai normal : quatorze jours)." }
      ] },
    { id: "vzb027", diff: 2, ctx: "Listen to a conversation between a student and the coordinator of a campus tutoring center.", names: {W:"Coordinator",M:"Student"}, lines: [
      ["W", "Thanks for coming in, Kevin. I've read your application. You're a second-year in economics, and you'd like to tutor first-year math."],
      ["M", "That's right. I got an A in both calculus courses, and I've helped friends with problem sets before."],
      ["W", "Good. Tell me about a time you explained something and the other person didn't understand at first. What did you do?"],
      ["M", "Well, my roommate couldn't understand derivatives. I started with the formulas, and she got more confused. So I switched to a real example, how fast a car's speed changes. After that it clicked for her."],
      ["W", "So you adapted. I like that. Tutoring is partly patience. How would you feel about a student who keeps making the same mistake?"],
      ["M", "I'd try to find out why. Usually there's a reason, like a missing basic skill. Then I'd practice that first."],
      ["W", "Good answer. Now the practical side. Sessions are forty-five minutes. The pay is twelve to fifteen dollars an hour, depending on experience, and you'd work six to eight hours a week."],
      ["M", "That works for me. Do I need any training?"],
      ["W", "There's a two-hour orientation on the first Monday of each term. We also ask tutors to complete a short online course on supporting students with learning differences."],
      ["M", "I'd be happy to do that."],
      ["W", "Great. I'll let you know by Friday."]],
      qs: [
      { q: "What is the purpose of the meeting?", o: ["A discussion of the student's grades in calculus.","A training session for new math tutors.","A complaint about a tutoring session.","A job interview for a position as a tutor."], a: 3, x: "La coordinatrice a lu sa candidature et l'interroge ; elle annonce sa réponse pour vendredi." },
      { q: "What did the student do when his roommate did not understand derivatives?", o: ["He gave her a longer list of formulas to learn by heart.","He suggested that she attend a session at the tutoring center.","He explained the idea with an example from daily life.","He asked another friend in his class to explain it to her."], a: 2, x: "Il a abandonné les formules pour l'exemple de la vitesse d'une voiture, et « it clicked for her »." },
      { q: "What does the coordinator's reaction to the roommate story suggest?", o: ["She values tutors who can adapt their explanations.","She thinks the student should have used formulas first.","She is worried that the student lacks patience.","She wants to offer him a higher rate of pay."], a: 0, x: "« So you adapted. I like that. » Elle apprécie la capacité à changer de méthode." }
      ] },
    { id: "vzb028", diff: 4, ctx: "Listen to a conversation between two junior analysts at an investment firm.", names: {W:"Woman",M:"Man"}, lines: [
      ["M", "So. \"Interesting.\""],
      ["W", "I know. I heard it too."],
      ["M", "Eleven minutes of presentation, and he says \"interesting.\" In four months of working for him, I've heard him say \"interesting\" about a typo, a rival's merger, and a rival's collapse."],
      ["W", "I think it's an all-purpose word, not a verdict. The follow-up question is the verdict. What did he ask?"],
      ["M", "He asked who had checked the discount rate."],
      ["W", "There you go. That wasn't curiosity. He thinks it's too low."],
      ["M", "Honestly, I think it's too low as well. I used the one from the template, and I assumed somebody would tell me if it was out of date."],
      ["W", "Somebody did, in effect, just now. In public, in front of a client, with that gentle look."],
      ["M", "Thanks. That's helpful in a way I won't enjoy until tomorrow."],
      ["W", "Look, rerun it with two other rates and bring him a one-page comparison before he asks. Showing you've seen the weakness is half of fixing it."],
      ["M", "And the other half?"],
      ["W", "Not blaming the template in the email. Even when it's true."],
      ["M", "Particularly when it's true. Right. Would you mind looking at the page before I send it?"],
      ["W", "I'll look. I'll say \"interesting\" if it's bad."]],
      qs: [
      { q: "What are the speakers mainly discussing?", o: ["Whether their client will accept the proposed discount rate.","Why the senior colleague is critical of every presentation.","How to interpret and respond to a senior colleague's reaction.","Who is responsible for the errors in the presentation template."], a: 2, x: "Ils décodent le « interesting » du supérieur et préparent la suite à donner ; le modèle de présentation n'est qu'un détail de la réponse." },
      { q: "What does the woman think his question about the discount rate shows?", o: ["He is curious how the rate was chosen.","He wants the analysts to explain the template.","He is satisfied with the figures in the deck.","He suspects the rate used is wrong."], a: 3, x: "« That wasn't curiosity. He thinks it's too low. » La vraie critique se trouve dans la question de suivi, pas dans « interesting »." },
      { q: "What does the woman advise the man to do?", o: ["Explain to the client why that particular template was used.","Offer a comparison of other rates without blaming the template.","Apologize in public at the next meeting of the whole team.","Wait and see whether the senior colleague raises the issue again."], a: 1, x: "Refaire le calcul avec deux autres taux et fournir une page de comparaison, sans accuser le modèle, « even when it's true »." }
      ] },
    { id: "vzb029", diff: 3, ctx: "Listen to a conversation between a student and an employee at a credit union.", names: {W:"Employee",M:"Student"}, lines: [
      ["M", "Hi. I got a text saying there was suspicious activity on my account, and it gave a number to call. I called it, and the person asked for my PIN, so I hung up."],
      ["W", "You were right to hang up. We would never ask for your PIN, by text or by phone. That was a phishing attempt."],
      ["M", "Phew. But, before that, I clicked the link in the text. Just once. Then I saw how odd the page looked and closed it."],
      ["W", "Did you type anything in? A password, a card number?"],
      ["M", "I typed my username. I don't think I pressed submit."],
      ["W", "Hmm. To be safe, we should change your online banking password now, and I'd suggest a new card as well. Is that okay?"],
      ["M", "Yes. Will I have to pay for the new card?"],
      ["W", "No, it's free when there's a security concern. It takes five working days to arrive, and the old one will be blocked at the end of today."],
      ["M", "Five days without a card. I have rent due on Friday."],
      ["W", "Then pay it by bank transfer. I can raise your daily transfer limit for the rest of the week, if you like."],
      ["M", "Okay. And is there any chance that somebody has already accessed my account?"],
      ["W", "Let me go through the last forty-eight hours with you. Nothing unusual so far. Everything here looks like you."]],
      qs: [
      { q: "Why has the student come to the credit union?", o: ["To ask for a new PIN because he lost his card last week.","To dispute a payment on his statement that he does not recognize.","To report a suspicious message and protect his account.","To find out why his account has been blocked since Monday."], a: 2, x: "Il a reçu un faux SMS, appelé un numéro suspect et cliqué sur un lien : il vient sécuriser son compte." },
      { q: "Why does the employee recommend a new card?", o: ["As a precaution, since he began entering details on a fake page.","Because the old card was used in a fraudulent transaction this week.","Because the credit union always blocks cards after a phishing attempt.","Because he gave his PIN to the person who answered the phone."], a: 0, x: "Il a commencé à saisir ses identifiants sur le faux site : par prudence, on change aussi la carte. Il n'a pas donné son PIN (il a raccroché)." },
      { q: "What does the employee mean by \"Everything here looks like you\"?", o: ["She suspects that a few of the transactions were made by someone he knows.","She finds no sign of unauthorized activity on his account.","She thinks the student should check his account more carefully.","She has proof that the student was not the victim of a scam."], a: 1, x: "Elle vérifie les 48 dernières heures et ne voit rien d'inhabituel : toutes les opérations correspondent à ses habitudes." }
      ] }
  );
  CONTENT.talk.push(
    { id: "tzb001", diff: 3, g: "W", ctx: "Listen to part of a lecture in an economics class.", text: "Let me start with a puzzle that confuses almost everyone the first time they meet it. Suppose a partner at a law firm is also the fastest typist in the office, twice as fast as her assistant. Should she type her own documents? Common sense says yes, since she's better at it. Economics says no, and the reason is comparative advantage, an idea David Ricardo set out in 1817. The key is to stop asking who is better at a task, which is called absolute advantage, and to ask instead what each person gives up in order to do it. Every hour the partner spends typing is an hour not spent with clients, and an hour with clients might earn her five hundred dollars. The assistant's hour is worth far less on the open market. So the assistant gives up less by typing, which means she has the comparative advantage in typing, even though she is slower. Total output is highest when each person specializes in what they give up least to do, and then they trade. Ricardo's own example involved wine from Portugal and cloth from England, and it showed that even a country that is more efficient at making everything gains from trading with a less efficient one. Now, a caveat, because this is where students tend to overreach. The theory shows that trade can make the total pie bigger. It doesn't say that everyone gets a larger slice. When a country opens up to trade, workers in the industries that lose out may face years of unemployment, while the gains are spread thinly across millions of consumers. Economists have been, I'd say, rather relaxed about this. The honest version is that the winners could compensate the losers and still come out ahead. But compensation is a political choice, and it is very often not made.",
      qs: [
      { q: "What is the main point of the lecture?", o: ["Countries should avoid trade in sectors where they are the least efficient.","Workers who type faster than their colleagues should always do the typing.","Total output rises most when each person performs the task they do best.","Gains from trade come from specializing in what costs the least to give up."], a: 3, x: "Idée centrale : l'avantage comparatif repose sur le coût d'opportunité, pas sur la supériorité absolue. Le dernier choix décrit l'avantage absolu, que le cours écarte." },
      { q: "Why does the professor describe the law firm partner and her assistant?", o: ["To explain why lawyers are normally paid more than their assistants.","To show that being the best at a task does not mean one should do it.","To argue that typing speed is the most valuable skill in an office.","To illustrate how wages are set in a competitive labor market for typists."], a: 1, x: "L'exemple sert à dissocier « être meilleur » et « devoir le faire » : la juriste perd davantage en tapant qu'en consacrant son heure à ses clients." },
      { q: "According to the professor, why does the assistant have the comparative advantage in typing?", o: ["She types more accurately than the partner when she works under pressure.","Her hourly wage is lower than that of every other employee in the firm.","Typing costs her less in forgone earnings than it costs the partner.","She spends more hours on typing tasks than the partner does each week."], a: 2, x: "Le coût d'opportunité d'une heure de frappe est plus faible pour elle (500 dollars pour la juriste), même si elle est plus lente." },
      { q: "What does the professor say about Ricardo's example of Portugal and England?", o: ["A country that is better at everything still gains from trading.","Portugal gained more from trading than England did in the example.","Trade works only when each country has the same costs of production.","England should have stopped producing cloth in order to make wine."], a: 0, x: "« even a country that is more efficient at making everything gains from trading with a less efficient one »." },
      { q: "What does the professor imply about the people who lose when a country opens to trade?", o: ["They quickly find better jobs in the industries that benefit from trade.","They are too few in number to affect the overall gains from trade.","They were mistaken about the benefits that trade would bring them.","They are not automatically compensated, since that is a political choice."], a: 3, x: "« compensation is a political choice, and it is very often not made » : les perdants ne sont pas dédommagés automatiquement." }
      ] },
    { id: "tzb002", diff: 4, g: "M", ctx: "Listen to part of a lecture in a finance class.", text: "The efficient market hypothesis says that asset prices already reflect all available information, which implies that nobody can consistently beat the market by analyzing public data. Eugene Fama formalized the idea in 1970, and for a generation it dominated finance departments. Today I want to look at a paradox buried inside it. In 1980, Sanford Grossman and Joseph Stiglitz pointed out that if prices fully reflected all information, nobody would have any reason to gather information in the first place. Research costs money. If the price already contains everything the research would reveal, then the researcher pays the cost and earns nothing, so rational investors would stop researching. But if everyone stops, prices stop reflecting information, and research becomes profitable again. The logical conclusion is that markets cannot be perfectly efficient. They must be inefficient to just the degree that rewards analysts for their trouble. So efficiency isn't a yes-or-no property but a matter of degree, determined by the cost of acquiring information. Notice what this does to the way we read the evidence. Study after study finds that, before fees, active managers do about as well as the index, and after fees they trail it by roughly the amount of the fees. Fans of the hypothesis cite that as vindication. But the Grossman and Stiglitz argument predicts something subtler: that the returns to skill should be roughly equal to its costs, which is more or less what we observe. Which is, if you think about it, a rather bleak equilibrium for the investors who pay those fees. It doesn't mean that no one ever has an edge. It means that edges are scarce, expensive to find, and quickly competed away. I'd put it this way. The market isn't a machine that has already computed the answer. It's a crowd of people paid to compute it, and the quality of the answer depends on how well they are paid.",
      qs: [
      { q: "What is the main point of the lecture?", o: ["Active managers rarely make a profit, so investors should avoid them altogether.","Markets cannot be fully efficient, since gathering information must be rewarded.","Prices never reflect information, so research is always profitable for investors.","Fama's hypothesis was proved wrong by the study that Grossman and Stiglitz published."], a: 1, x: "Le paradoxe montre que l'efficience parfaite est impossible : il faut que la recherche soit rémunérée. Il ne réfute pas totalement l'hypothèse mais la transforme en question de degré." },
      { q: "What problem would arise if prices fully reflected all information?", o: ["Investors would have no reason to pay for research.","Analysts would be unable to understand published prices.","Prices would no longer change from one day to the next.","Fees for active managers would rise above their costs."], a: 0, x: "Si le prix contient déjà toute l'information, la recherche coûte sans rapporter : plus personne n'a intérêt à la faire." },
      { q: "How does the speaker interpret the finding that active funds trail the index after fees?", o: ["As evidence that managers have no skill whatsoever, even before any fees.","As a failure of the paradox to explain how professional investors actually behave.","As proof that the market is far more efficient than the paradox suggests.","As consistent with the paradox, since the gains from skill cover its costs."], a: 3, x: "Avant frais, les gérants égalent l'indice ; après frais, ils sont en retard du montant des frais. C'est ce que prédit l'argument : le rendement de l'habileté couvre son coût. Les partisans de l'hypothèse y voient une preuve plus simple." },
      { q: "What does the speaker mean by calling the equilibrium \"rather bleak\"?", o: ["Analysts are paid too little for the research that they do.","Markets will eventually become inefficient and collapse completely.","Investors who pay active management fees gain little in return.","Passive funds are likely to perform worse than active funds."], a: 2, x: "L'équilibre est sombre pour ceux qui paient les frais : ils n'obtiennent pas de surperformance nette." },
      { q: "What does the speaker suggest with the image of a \"crowd of people paid to compute\" the answer?", o: ["The accuracy of prices depends on how well information gathering is rewarded.","Market prices are produced by a few well-informed investors working together.","Computers now calculate prices better than any crowd of analysts could.","Prices become more accurate as more people take part in the market."], a: 0, x: "La métaphore : le prix n'est pas une réponse déjà calculée, mais le produit du travail d'agents que l'on rémunère ; sa qualité dépend donc de cette rémunération." }
      ] },
    { id: "tzb003", diff: 2, g: "W", ctx: "Listen to part of a lecture in an accounting class.", text: "Imagine you run a gym. On the first of January, a customer pays you twelve hundred dollars for a one-year membership. Your bank account is now twelve hundred dollars richer. So, have you earned twelve hundred dollars in January? Under cash accounting, which records money when it moves in or out, the answer is yes. But most companies use accrual accounting, and under accrual accounting, the answer is no. Accrual accounting follows a principle called revenue recognition: you record revenue when you have earned it, by providing the service, not when the money arrives. Your customer has paid for twelve months of access, and in January you have provided only one of them. So you record one hundred dollars of revenue in January, and the other eleven hundred is recorded as a liability, called deferred revenue, because you still owe the customer eleven months of service. Each month, one hundred dollars moves from the liability to revenue. Expenses work in a similar way, under what's called the matching principle. If you pay for a year of insurance in advance, you don't treat the whole amount as an expense in the month you pay. You spread it over the year that it protects. Why bother? Because cash can be misleading. Without accrual accounting, the gym would look wildly profitable in January, when memberships are sold, and as if it were losing money in summer, even though the business is just as healthy in both months. Accrual accounting gives a more stable picture of performance. It does have a limit, though. A company can show profits on paper and still run out of cash, for example if its customers are slow to pay. So analysts look at both: the income statement for performance, and the cash flow statement for survival.",
      qs: [
      { q: "What is the main purpose of the lecture?", o: ["To show why gyms are more profitable in January than in summer.","To compare the costs of different types of insurance.","To explain how accrual accounting records revenue and expenses.","To argue that cash accounting should no longer be used."], a: 2, x: "Le cours oppose comptabilité de caisse et comptabilité d'engagement, à l'aide de l'exemple d'une salle de sport." },
      { q: "How much revenue does the gym record in January for the one-year membership?", o: ["Twelve hundred dollars.","Eleven hundred dollars.","Six hundred dollars.","One hundred dollars."], a: 3, x: "Un mois sur douze a été fourni : 1 200 / 12 = 100 dollars de produit ; le reste est un produit constaté d'avance." },
      { q: "What is deferred revenue?", o: ["Money that customers have not yet paid to the company for a service.","Money received for a service the company still has to provide.","Profit that the company plans to earn in the following year.","The portion of revenue that is spent on insurance each year."], a: 1, x: "Le produit différé est une dette envers le client (« you still owe the customer eleven months of service »), pas une créance sur lui." },
      { q: "Why does the professor mention insurance paid in advance?", o: ["To show that insurance is the main expense of a gym.","To explain why customers pay for a year in advance.","To illustrate the matching principle for expenses.","To prove that expenses are always recorded in cash."], a: 2, x: "Même logique que pour les produits : on répartit la charge sur la période qu'elle couvre (principe de rattachement)." },
      { q: "According to the professor, how can a company show a profit and still run out of cash?", o: ["Its expenses are spread over a much longer period of time.","Its customers may take a long time to pay what they owe.","Its revenue is recorded before the end of the year.","Its analysts use only the income statement to judge it."], a: 1, x: "Le bénéfice comptable inclut des ventes non encore encaissées : « customers are slow to pay ». D'où l'utilité du tableau des flux de trésorerie." }
      ] },
    { id: "tzb004", diff: 4, g: "M", ctx: "Listen to part of a lecture in a behavioral science class.", text: "Suppose I offer you a hundred dollars today or a hundred and ten tomorrow. Most people take the hundred today. Now suppose I offer you a hundred dollars in thirty days or a hundred and ten in thirty-one. Most people now wait for the hundred and ten. Look at that carefully. The choice is the same, one extra day for ten more dollars, and yet the answer flips depending on whether the reward is near. A rational agent with a constant discount rate would answer both questions in the same way. Behavioral economists call this present bias, and the standard model is hyperbolic discounting, in which the value we place on waiting drops steeply in the immediate future and flattens out later on. The consequence is a conflict between selves. Today's self decides, in January, that next month's self will go running at six every morning. Next month's self, in a warm bed, has other ideas. Economists then ask whether people understand this about themselves. The naive don't, and keep making plans they won't keep. The sophisticated do, and they look for what's called a commitment device, a way of binding your future self. The name comes from Ulysses, who had himself tied to the mast so that he could hear the sirens without steering toward them. Modern versions are less dramatic: savings accounts you can't touch until retirement, or contracts in which you forfeit money to a friend if you miss your goal. Here's the part I find most telling. Some people knowingly pay for such restrictions, accepting lower interest rates and penalties. That's behavior hard to explain if we are all consistently rational. Nobody pays to limit their options unless they don't quite trust themselves.",
      qs: [
      { q: "What is the main topic of the lecture?", o: ["How present bias makes choices inconsistent and how people resist it.","Why most people would rather have money today than money in the future.","How special savings accounts help people to earn higher rates of interest.","Why rational agents make exactly the same decision at all times and places."], a: 0, x: "Le cours part du renversement de préférence et débouche sur les dispositifs d'engagement. Préférer le présent n'est que le point de départ." },
      { q: "Why does the professor compare the two choices, today versus tomorrow and thirty days versus thirty-one?", o: ["To prove that people always prefer smaller rewards that arrive sooner.","To demonstrate that ten dollars is too small to influence a decision.","To explain why waiting for a month costs more than waiting for one day.","To show that preferences flip when the same delay is moved further away."], a: 3, x: "Le décalage d'un jour est identique dans les deux cas ; seul change l'éloignement de la récompense, et le choix s'inverse." },
      { q: "According to the lecture, how do sophisticated people differ from naive people?", o: ["They set fewer goals for their future selves than naive people do.","They discount the future at a constant rate, unlike naive people.","They know about their present bias and try to restrain themselves.","They choose larger rewards even when these arrive very soon."], a: 2, x: "Les naïfs ignorent leur biais et refont des plans qu'ils ne tiendront pas ; les sophistiqués le savent et cherchent à se lier les mains." },
      { q: "Why does the professor mention Ulysses?", o: ["He is an example of a decision maker with constant preferences.","He shows what happens to people who ignore their future selves.","He proves that ancient people understood present bias.","He is an example of someone who used a commitment device."], a: 3, x: "Ulysse s'est fait attacher au mât pour ne pas céder aux sirènes : il lie son futur moi, c'est la définition du dispositif d'engagement." },
      { q: "What does the professor imply about people who accept penalties in exchange for restrictions?", o: ["They recognize that their future choices may not match their goals.","They are irrational because they reject interest that they could earn.","They understand financial products better than other savers.","They have a constant discount rate for all future rewards."], a: 0, x: "Payer pour réduire ses options suppose que l'on se méfie de soi-même : la remarque finale ironise sur l'idée d'un agent parfaitement cohérent." }
      ] },
    { id: "tzb005", diff: 3, g: "W", ctx: "Listen to part of a lecture in a social science class.", text: "In 1902, the French colonial government of Hanoi had a rat problem. The new sewer system had become a breeding ground, so officials offered a bounty: bring in a rat's tail and get paid. At first it seemed to work, and thousands of tails arrived. But then inspectors began to notice rats running around without tails. Hunters had realized that it was more profitable to cut off the tail and release the rat, so that it could breed and produce more tails. Some people, apparently, began raising rats. The story is a perfect illustration of what's called Goodhart's law, after the British economist Charles Goodhart, who formulated it about monetary policy in the 1970s. The popular version goes: when a measure becomes a target, it ceases to be a good measure. Tails were a decent indicator of dead rats, as long as nobody had a reason to produce tails. Once payment depended on the tails, people optimized for the tails. We see the same pattern everywhere. Hospitals judged on waiting times have been caught reclassifying patients. Schools judged on test scores drift toward teaching to the test. Traders paid on short-term profit take risks that don't show up until later. Notice that nobody has to be especially dishonest. People simply respond to incentives, and the measure, which was only ever a stand-in, becomes disconnected from the thing we actually cared about. So what's the remedy? There's no perfect one. Using several indicators makes gaming harder, because it's difficult to manipulate them all at once. Rotating the measures helps. And, perhaps most important, keeping human judgment in the loop, someone who understands what the number was meant to stand for. Numbers are valuable. We just shouldn't ask them to do our thinking.",
      qs: [
      { q: "What is the main idea of the lecture?", o: ["Colonial governments often failed to solve problems of public health.","A measure loses its value as an indicator once people are paid to hit it.","People who respond to incentives are usually dishonest.","Statistics are unreliable and should not be used to evaluate performance."], a: 1, x: "C'est l'énoncé de la loi de Goodhart : quand une mesure devient un objectif, elle cesse d'être une bonne mesure. Le cours ne rejette pas les chiffres, il met en garde contre leur usage." },
      { q: "Why did inspectors notice rats without tails?", o: ["The rats were losing their tails because of a disease in the sewers.","Officials had stopped paying for tails and the hunters stopped killing rats.","Hunters cut off the tails and released the rats so they would breed.","Hunters had decided to keep the rats to sell as pets."], a: 2, x: "Les chasseurs coupaient la queue et relâchaient le rat pour qu'il se reproduise et produise d'autres queues à vendre." },
      { q: "What does the professor say about the rat tails before the bounty was introduced?", o: ["They were the only way to count the rats in the sewers.","They were a reasonable sign that rats had been killed.","They had no value for the officials in charge of the sewers.","They were an unreliable sign because rats often lose their tails."], a: 1, x: "« Tails were a decent indicator of dead rats, as long as nobody had a reason to produce tails »." },
      { q: "What does the professor mean by \"nobody has to be especially dishonest\"?", o: ["Cheating is actually rather rare in hospitals, schools and banks.","Managers who set targets are always honest about the results.","People who game measures usually fail to understand incentives.","Ordinary reactions to incentives are enough to cause the problem."], a: 3, x: "Le comportement détourné est une réponse normale aux incitations ; il n'y a pas besoin de supposer la malhonnêteté." },
      { q: "According to the professor, what is most important in reducing the problem?", o: ["Involving someone who understands what the measure represents.","Replacing every number with a short qualitative description of results.","Changing the target every single time a new problem is discovered.","Increasing the payment for each unit that is being measured."], a: 0, x: "« perhaps most important, keeping human judgment in the loop ». La rotation et la pluralité des indicateurs aident, mais ne sont pas jugées les plus importantes." }
      ] },
    { id: "tzb006", diff: 2, g: "M", ctx: "Listen to part of a lecture in a history class.", text: "Why did the Industrial Revolution begin in Britain in the late eighteenth century, and not in France, China, or the Netherlands? Historians have debated this for generations, and none of the answers is complete, but several factors come up again and again. The first is coal. Britain had large coal deposits close to its cities and ports, and as wood became scarce and expensive, coal became the cheaper fuel. That created an incentive to develop machines that used it. Thomas Newcomen's steam engine, built in 1712, was first used to pump water out of coal mines. The second factor is labor costs. Wages in Britain were relatively high, while energy was cheap, so factory owners had a reason to invest in machines that saved labor. In countries where workers were cheap, machines were less attractive. Third, Britain had capital and markets. London was a financial center, with banks and a stock market that could fund new businesses, and the British navy and its colonies provided access to markets and raw materials, particularly cotton. Finally, there is the question of ideas. Britain had a culture that valued practical science, and inventors such as James Watt worked alongside instrument makers and engineers. Patent law gave inventors a chance to profit from their work. Now, a note of caution. None of these factors alone is a satisfying explanation. Other countries had some of them. What was distinctive was the combination, and probably an element of luck as well. So when you come across a book that promises the one reason for the Industrial Revolution, be suspicious.",
      qs: [
      { q: "What is the main point of the lecture?", o: ["Several factors together explain why industrialization began in Britain.","Coal was the single cause of the Industrial Revolution in Britain.","Britain industrialized first because it had the best scientists in Europe.","Historians have agreed on why Britain industrialized before other countries."], a: 0, x: "Le cours présente plusieurs facteurs et conclut que c'est leur combinaison qui est distinctive. Aucun facteur seul n'est une explication satisfaisante." },
      { q: "Why was coal important for the development of machines?", o: ["It was easier to transport than wood, which reduced the cost of shipping goods.","It replaced human labor, which was too expensive in the mines.","It was found in other countries, which wanted to buy British machines.","Cheap coal replaced scarce wood, which encouraged machines that used it."], a: 3, x: "Le bois devenant rare, le charbon était moins cher ; cela incitait à inventer des machines qui l'utilisaient (par exemple pour pomper l'eau des mines)." },
      { q: "According to the professor, why did high wages encourage industrialization?", o: ["Workers could afford to buy the goods that the machines produced.","Owners had a reason to buy machines that saved labor.","Factory owners wanted to pay their workers higher wages.","Workers could buy their own machines for working at home."], a: 1, x: "Salaires élevés + énergie bon marché : il devenait rentable d'investir dans des machines économisant le travail." },
      { q: "Why does the professor say that readers should be suspicious of books that promise \"the one reason\"?", o: ["Most historians who write books about the subject are not reliable.","The Industrial Revolution happened by chance and has no real causes.","No single factor adequately explains the Industrial Revolution.","The reasons for the Industrial Revolution cannot be known."], a: 2, x: "« None of these factors alone is a satisfying explanation... the combination, and probably an element of luck ». Le chercheur n'affirme pas que tout est hasard." }
      ] },
    { id: "tzb007", diff: 4, g: "W", ctx: "Listen to part of a lecture in a literature class.", text: "Most of us read a first-person narrator the way we listen to a friend: we assume they're telling us the truth, or at least what they believe to be true. The unreliable narrator exploits that trust. My favorite example is Kazuo Ishiguro's novel The Remains of the Day, which won the Booker Prize in 1989. The narrator, Stevens, is an English butler who, in 1956, takes a motoring trip across England and uses the journey to look back over his career at Darlington Hall. Stevens never lies, exactly. He is sincere. What makes him unreliable is that he has organized his whole life around an idea of dignity, which means never showing feeling and never questioning his employer. So when he recalls that Lord Darlington, who sympathized with Nazi Germany between the wars, dismissed two Jewish maids, Stevens describes it as a regrettable matter and moves on. And when he recounts his relationship with the housekeeper, Miss Kenton, he reports every sign that she cared for him, and every sign that he cared for her, and then explains it away as professional friction. The reader sees what he cannot. Critics call this dramatic irony: the gap between what a narrator says and what the text allows us to understand. Why does it matter? A reliable narrator could simply have told us that Stevens wasted his life serving a man who did not deserve it. By having Stevens tell the story, Ishiguro makes us do the work of reading against him, and that effort, I'd argue, makes the pain of the ending far sharper than any confession could. The novel's real subject isn't the past. It's self-deception.",
      qs: [
      { q: "What is the lecture mainly about?", o: ["Why English butlers were important in the history of British literature.","How Ishiguro's novel describes political events in the 1930s.","The reasons why The Remains of the Day won a major prize.","How an unreliable narrator in a novel shapes the reader's understanding."], a: 3, x: "Le cours utilise le roman pour expliquer le narrateur peu fiable. L'arrière-plan politique et le prix ne sont que des détails." },
      { q: "According to the lecture, what makes Stevens an unreliable narrator?", o: ["He deliberately lies to the reader about his employer's politics.","He sincerely misreports events that conflict with his idea of dignity.","He forgets important details about his long career at Darlington Hall.","He tells the story many years after the events took place."], a: 1, x: "« Stevens never lies, exactly. He is sincere » : son manque de fiabilité vient d'un aveuglement lié à sa conception de la dignité, pas d'un mensonge." },
      { q: "Why does the professor mention the dismissal of the two maids?", o: ["To show how Stevens treats a serious matter as merely regrettable.","To prove beyond doubt that Lord Darlington sympathized with Nazi Germany.","To explain why Stevens decides to leave Darlington Hall.","To illustrate the housekeeper's disapproval of her employer."], a: 0, x: "Stevens évoque l'affaire comme une simple regrettable affaire : exemple de la distance entre ce qu'il dit et ce que le lecteur comprend." },
      { q: "What does the professor mean by saying that the reader \"does the work of reading against\" Stevens?", o: ["Readers must reject everything that Stevens says as false.","Readers must research the history of the period to understand the novel.","Readers must interpret events differently from the narrator.","Readers must read the novel twice to appreciate its ending."], a: 2, x: "Le lecteur doit reconstituer ce que Stevens refuse de voir ; il ne rejette pas tout son récit, qui est sincère." },
      { q: "What is the professor's view of the novel's main theme?", o: ["Stevens deceives himself about his own life.","Loyalty to an employer is a form of dignity.","Memory is less reliable than documents of the period.","Love is impossible in a rigid social class system."], a: 0, x: "Conclusion explicite : « The novel's real subject isn't the past. It's self-deception. »" }
      ] },
    { id: "tzb008", diff: 3, g: "M", ctx: "Listen to part of a lecture in an economics class.", text: "In 1970, George Akerlof, then a young economist, wrote a paper that was rejected by several journals before one finally published it. It later helped him win a Nobel Prize. The paper was about used cars, and its title was \"The Market for Lemons.\" In American slang, a lemon is a car that turns out to be defective. Akerlof's insight was about information. The seller of a used car knows its history. The buyer doesn't. Suppose half the cars on the market are good and worth ten thousand dollars, and half are lemons worth four thousand. A buyer who can't tell them apart will offer something like the average, say seven thousand. But at that price, the owners of good cars won't sell, because they'd lose three thousand dollars. Only the owners of lemons are happy to sell. So the average quality of the cars on the market falls, buyers realize it and lower their offers, and now even more owners of decent cars withdraw. In the extreme case, the market collapses: good cars disappear, and only lemons trade. This is called adverse selection. The remarkable thing is that nobody has to be dishonest. The problem comes from the asymmetry of information alone. Of course, real used-car markets still exist, which means that people have found ways around the problem. Warranties signal that the seller believes in the car. Independent inspections reduce the buyer's uncertainty. Reputation matters, and so does certification by a respected dealer. The same logic appears well beyond cars: in insurance, where those most likely to fall ill are the keenest to buy health cover, and in labor markets, where employers can't observe how good a worker is. Akerlof's lesson is that markets don't just need buyers and sellers. They need trust, or institutions that stand in for it.",
      qs: [
      { q: "What is the main idea of the lecture?", o: ["Used cars are a poor investment for most buyers.","Sellers of used cars are usually dishonest about their cars' condition.","Unequal information between buyers and sellers can destroy a market.","Prices on a market always rise when the quality of goods falls."], a: 2, x: "Akerlof montre que l'asymétrie d'information fait fuir les bons produits. Le texte précise que personne n'a besoin d'être malhonnête." },
      { q: "Why do owners of good cars withdraw from the market in Akerlof's example?", o: ["Buyers are unwilling to pay for any car with an unknown history.","They are afraid that their cars will turn out to be lemons.","They are unable to prove that their cars are in good condition.","The average price offered is lower than the value of their cars."], a: 3, x: "Prix moyen proposé : 7 000 pour une voiture qui en vaut 10 000 : ils perdraient 3 000 dollars." },
      { q: "What does the professor mean by \"nobody has to be dishonest\"?", o: ["Sellers are legally required to tell buyers about the history of cars.","The collapse can occur simply because sellers know more than buyers.","Honest buyers can always identify which cars are lemons.","Dishonest sellers are quickly removed from the market."], a: 1, x: "Le mécanisme repose sur l'asymétrie d'information seule, sans tromperie." },
      { q: "Why does the professor mention warranties and inspections?", o: ["They are the main reason why used cars are so expensive today.","They are ways of reducing the problem of unequal information.","They explain why lemons are rarely sold by dealers.","They show that Akerlof's theory is incorrect."], a: 1, x: "Ce sont des solutions pratiques : signal de confiance (garantie) et réduction de l'incertitude (inspection). Elles n'invalident pas la théorie." },
      { q: "Why does the professor mention health insurance?", o: ["It is a better example of adverse selection than used cars.","It proves that insurance companies have better information than their customers.","It explains why people with good health avoid buying insurance.","It shows that the same logic applies to markets other than used cars."], a: 3, x: "Les personnes les plus susceptibles de tomber malades achètent le plus volontiers : même sélection adverse, dans un autre marché." }
      ] },
    { id: "tzb009", diff: 4, g: "M", ctx: "Listen to part of a lecture in a finance class.", text: "Hyman Minsky was an economist who spent most of his career on the margins of the profession and died in 1996. After 2008, journalists suddenly rediscovered him, and the phrase \"Minsky moment\" entered financial vocabulary. His central claim, the financial instability hypothesis, is paradoxical: stability is destabilizing. When times are good for long enough, firms and lenders come to believe that they will stay good. Lenders relax their standards, borrowers take on more debt, and the economy gradually moves from safe finance to fragile finance. Minsky distinguished three stages. In hedge finance, a borrower's income covers both the interest and the principal. In speculative finance, income covers only the interest, so the borrower has to keep refinancing the principal, which works as long as credit is available. And in Ponzi finance, income doesn't even cover the interest, and the borrower depends on rising asset prices to keep going. Nothing in this description requires fraud. A homeowner who is betting on rising house prices is in a Ponzi position in Minsky's sense. The critical point is that a system dominated by speculative and Ponzi borrowers is extremely vulnerable to a small shock. If lenders become cautious, refinancing stops, borrowers are forced to sell assets, prices fall, and the fall makes the next borrower's position worse. That sudden collapse is the Minsky moment. Now, a note of skepticism. Mainstream economists were slow to take Minsky seriously, partly because he offered no neat mathematical model, and partly because his theory is hard to test: it tells you that a crisis will come, but not when. Both objections are fair. Yet I'd say that a theory which says complacency is the cause of fragility has at least earned a place on the reading list.",
      qs: [
      { q: "According to Minsky, why does a long period of stability create risk?", o: ["Governments reduce regulation when the economy has been stable for years.","Lenders become unable to refinance the loans they have made.","People come to believe that good times will last, so they borrow more.","Asset prices stop rising once the economy has become stable."], a: 2, x: "« stability is destabilizing » : la confiance entraîne un relâchement des critères de prêt et un endettement croissant." },
      { q: "What characterizes speculative finance?", o: ["Income pays the interest, but the principal must be refinanced.","Income covers neither the interest nor the principal of the debt.","Borrowers rely on the sale of assets to pay all of their debts.","Income pays both the interest and the principal on time."], a: 0, x: "Speculative = revenus couvrant seulement les intérêts ; le principal doit être refinancé tant que le crédit existe. Hedge couvre les deux ; Ponzi ne couvre même pas les intérêts." },
      { q: "Why does the professor say a homeowner could be in a \"Ponzi position\"?", o: ["The homeowner depends on rising prices, though nothing illegal is involved.","The homeowner has deceived the bank about his or her income.","The homeowner has borrowed money from other homeowners.","The homeowner has promised high returns to people who lent him money."], a: 0, x: "« Nothing in this description requires fraud » : « Ponzi » désigne ici la dépendance à la hausse des prix, pas une escroquerie." },
      { q: "Why did mainstream economists hesitate to accept Minsky's theory?", o: ["It was published after the financial crisis of 2008 had already happened.","It had no mathematical model and cannot predict when crises happen.","It claimed that crises were caused by fraud rather than by borrowing.","It contradicted what historical evidence showed about earlier crises."], a: 1, x: "Deux critiques citées : pas de modèle mathématique net, et théorie difficile à tester (elle ne donne pas la date)." },
      { q: "What is the professor's attitude toward Minsky's theory?", o: ["It is mainly a product of the 2008 crisis and has no lasting value.","It is superior to the mainstream theories because it was correct.","It has limits, but it deserves to be studied.","It should be dismissed until it has been tested mathematically."], a: 2, x: "« Both objections are fair. Yet... has at least earned a place on the reading list » : nuance, ni rejet ni enthousiasme total." }
      ] },
    { id: "tzb010", diff: 2, g: "W", ctx: "Listen to part of a lecture in a behavioral science class.", text: "Imagine two countries. In the first, when you get a driver's license, you tick a box if you want to be an organ donor. In the second, you are assumed to be a donor unless you tick a box to say no. Do you think the donation rates would be different? In 2003, two researchers, Eric Johnson and Daniel Goldstein, compared European countries and found a dramatic gap. In Germany, where people must opt in, only about twelve percent had agreed to be donors. In neighboring Austria, where people must opt out, the figure was close to a hundred percent. People in the two countries have similar attitudes toward donation, so why this huge difference? The answer is the default effect. Most people stick with whatever option is already selected for them. Changing it takes effort, and it requires us to make a decision, which many people prefer to avoid. We also tend to read the default as a recommendation: if the authorities set it up this way, maybe it's the right choice. Policy makers have noticed. The default is one of the best-known nudges, a term from Richard Thaler and Cass Sunstein for a small change in the way choices are presented that steers people without forbidding any option. Companies use defaults too, for example by automatically enrolling employees in retirement savings plans, which greatly increases participation. But I want to add a caution about the organ donation story. Later studies found that changing the default does not automatically produce more transplants. Actual donations also depend on how hospitals are organized and on whether families consent. So defaults matter a lot, but they are only one part of the picture.",
      qs: [
      { q: "What is the main purpose of the lecture?", o: ["To compare attitudes toward organ donation in two countries.","To persuade students in the class to become organ donors themselves.","To show that governments should force people to make choices.","To explain the default effect using the example of organ donation."], a: 3, x: "L'exemple du don d'organes illustre l'effet de statut par défaut. Les attitudes sont jugées similaires dans les deux pays." },
      { q: "What did Johnson and Goldstein find about Germany and Austria?", o: ["People in Austria held more positive attitudes toward donation.","Both countries had donation rates of around twelve percent.","Far more people were donors in the country with an opt-out system.","Fewer Austrians than Germans had agreed to be organ donors in the study."], a: 2, x: "Allemagne (opt-in) : environ 12 % ; Autriche (opt-out) : proche de 100 %." },
      { q: "According to the professor, why do people tend to keep the default option?", o: ["They do not realize that they are allowed to change the default.","They are afraid that the authorities will punish them for changing it.","They have already considered the alternatives and prefer the default.","Changing it takes effort and they may read it as a recommendation."], a: 3, x: "Deux raisons : l'effort de changement et l'idée que le choix par défaut est recommandé par les autorités." },
      { q: "What is a \"nudge\"?", o: ["A small change in presentation that steers choices but bans nothing.","A law that forces people to choose one option rather than another.","A financial reward that encourages people to save money.","A warning that explains in detail the risks of a decision."], a: 0, x: "Définition donnée : un petit changement dans la présentation qui oriente sans interdire aucune option." },
      { q: "What caution does the professor give about the organ donation example?", o: ["The figures from Germany and Austria were collected incorrectly.","Changing the default does not by itself guarantee more transplants.","The default effect disappears when people are asked to explain their choices.","Families of donors are usually opposed to organ donation."], a: 1, x: "Les études ultérieures montrent que les dons réels dépendent aussi de l'organisation des hôpitaux et de l'accord des familles." }
      ] },
    { id: "tzb012", diff: 3, g: "M", ctx: "Listen to part of a lecture in an economic history class.", text: "When the plague reached Europe in 1347, it killed somewhere between a third and a half of the population within a few years. We usually think of it as an unmitigated catastrophe, and for those who lived through it, it certainly was. But economic historians find it fascinating because it works like a brutal natural experiment: what happens to an economy when labor suddenly becomes scarce, while land and tools stay the same? Basic economics predicts that workers become more valuable. And that's what we see. In England, wages for farm laborers rose sharply in the years after 1348, and peasants began to move in search of better pay, leaving landlords unable to find hands to bring in their harvests. The authorities reacted quickly. In 1351, Parliament passed the Statute of Labourers, which tried to freeze wages at pre-plague levels and to forbid workers from leaving their employers. The statute was difficult to enforce. Employers needed workers badly enough to break it, and many did, paying more than the law allowed. Over the next century, serfdom, the system in which peasants were tied to the land, declined in much of Western Europe. But we should not conclude that scarcity always empowers workers. In Eastern Europe, the same shortage of labor led to the opposite result. There, landowners were politically stronger and the towns weaker, and they used their power to bind peasants more tightly to the land, a development historians call the second serfdom. So the plague did not have a single economic consequence. What mattered was not simply how many workers survived, but who held the power to decide the terms on which they worked.",
      qs: [
      { q: "What is the main point of the lecture?", o: ["The plague ended serfdom throughout all of Europe within a century.","Governments were unable to respond to the economic effects of the plague.","Wages rise whenever the population of a country declines.","The effects of the plague on labor depended on who held power."], a: 3, x: "Conclusion : ce n'est pas seulement le nombre de survivants qui comptait, mais qui décidait des conditions de travail. L'Europe de l'Est contredit la généralisation." },
      { q: "Why does the professor call the plague a \"natural experiment\"?", o: ["Historians were able to repeat the experiment in different countries.","The number of workers fell suddenly while land and tools did not change.","Scientists have since reproduced the plague under controlled conditions.","The plague affected rich and poor people in exactly the same way."], a: 1, x: "Une variable (le travail) change brutalement alors que les autres restent constantes : c'est la logique d'une expérience naturelle." },
      { q: "Why was the Statute of Labourers difficult to enforce?", o: ["Many employers broke it because they needed workers.","Parliament refused to pay officials to monitor wages.","Workers formed associations that opposed the statute.","Landowners were unable to move away from their estates."], a: 0, x: "« Employers needed workers badly enough to break it »." },
      { q: "How did the situation in Eastern Europe differ from that in England?", o: ["Landowners used their stronger position to tie peasants to the land.","Towns encouraged many peasants to leave the countryside for the cities.","Wages for laborers rose more quickly than in Western Europe.","The plague killed fewer people than it did in Western Europe."], a: 0, x: "À l'Est, les seigneurs plus puissants et les villes plus faibles ont renforcé l'attache à la terre (seconde servitude)." },
      { q: "What does the professor imply about economic explanations based on scarcity alone?", o: ["They are correct for Western Europe but incorrect for Eastern Europe.","They are incomplete because they ignore political power.","They cannot be tested because the plague was unique.","They overestimate how quickly wages respond to labor shortages."], a: 1, x: "L'économie de base prédit la hausse des salaires, mais le contre-exemple de l'Est montre que le rapport de force politique doit être pris en compte." }
      ] },
    { id: "tzb013", diff: 4, g: "W", ctx: "Listen to part of a lecture in a history class.", text: "When did Rome fall? Even that question is controversial. The traditional date is 476, when the last western emperor, Romulus Augustulus, was deposed. But few people living in Italy that year would have noticed a difference. Edward Gibbon, whose Decline and Fall of the Roman Empire appeared in 1776, gave the story its classic shape: a great civilization eroded from within by moral decay, and, in his view, by the rise of Christianity, before barbarians delivered the final blow. In the 1970s, a different school emerged, associated with Peter Brown, who developed the concept of late antiquity. Brown and his followers stressed continuity and transformation. The Roman world didn't end; it changed, with new religious, artistic and cultural forms, and new kingdoms that kept many Roman institutions, such as law and taxation, alive. Their vocabulary was telling: transformation instead of fall, accommodation instead of invasion. Then, in 2005, the archaeologist Bryan Ward-Perkins published a deliberate counterblast, The Fall of Rome and the End of Civilization. His evidence is material. After about the year 400, in Britain and elsewhere in the west, the quality of pottery declines, coinage becomes rarer, and buildings become smaller and are built of wood instead of stone. Ordinary people, he argues, became poorer, and that is hard to describe as a transformation. Notice that both camps can be right about different things. The elite culture of the Church and the courts may well have continued, while the living standards of ordinary people fell. And I'd suggest that the choice of words does real work. To call it a fall is to tell a story about loss. To call it a transformation is to tell a story about adaptation. Neither is a neutral description, and a good historian knows which story she is telling.",
      qs: [
      { q: "What is the main point of the lecture?", o: ["Historians have shown that the Roman Empire definitely ended in the year 476.","The decline of Rome was caused mainly by the rise of Christianity.","Archaeology has settled the debate over how Roman society ended.","The words used to describe Rome's end reflect different interpretations."], a: 3, x: "Le cours présente trois lectures successives (Gibbon, Brown, Ward-Perkins) et insiste sur le poids des mots choisis. Le débat n'est pas tranché." },
      { q: "What did Peter Brown and his followers emphasize?", o: ["The role of barbarian invasions in destroying Roman law.","The economic decline of ordinary people after the year 400.","Continuity and change in Roman culture and institutions.","The moral decay of the Roman elite before the fall."], a: 2, x: "L'école de la « late antiquity » parle de transformation et d'accommodation, avec le maintien du droit et de la fiscalité." },
      { q: "What kind of evidence does Ward-Perkins use?", o: ["Written accounts by Romans who personally lived through the decline.","Records of laws and taxes in the new kingdoms.","Physical remains showing a decline in everyday goods and buildings.","Descriptions of the Church and the courts after 400."], a: 2, x: "« His evidence is material » : poterie, monnaie, bâtiments. Il s'appuie sur l'archéologie, non sur des textes." },
      { q: "Why does the professor say that both sides \"can be right about different things\"?", o: ["Elite institutions may have survived while ordinary people grew poorer.","Gibbon and Brown described different periods of Roman history.","Ward-Perkins studied only Britain, while Brown studied the whole empire.","Both interpretations are equally supported by archaeological evidence."], a: 0, x: "Culture d'élite (Église, tribunaux) peut avoir perduré, tandis que le niveau de vie populaire baissait : deux thèses compatibles." },
      { q: "What is the purpose of the professor's final remarks?", o: ["To argue that historians should avoid using words like fall or transformation.","To suggest that the words historians choose shape the story they tell.","To criticize historians who change their interpretation of Rome.","To show that Gibbon's interpretation is more neutral than Brown's."], a: 1, x: "« Neither is a neutral description » : fall = récit de perte, transformation = récit d'adaptation. L'historien doit savoir quelle histoire il raconte." }
      ] },
    { id: "tzb014", diff: 3, g: "M", ctx: "Listen to part of a lecture in an economics class.", text: "Few topics in economics generate more heat than the minimum wage. The textbook model is straightforward: if you set the price of labor above the level where supply meets demand, employers will hire fewer workers, so unemployment rises. For decades, most economists accepted this. Then, in 1994, David Card and Alan Krueger published a study that challenged the consensus. In April 1992, New Jersey raised its minimum wage from four twenty-five to five oh five an hour. Card and Krueger surveyed fast-food restaurants in New Jersey and, for comparison, in neighboring eastern Pennsylvania, where the minimum stayed the same. If the textbook was right, New Jersey restaurants should have cut jobs relative to Pennsylvania. They didn't. If anything, employment in New Jersey rose slightly. The result caused enormous controversy. Critics, including David Neumark and William Wascher, re-examined the question using payroll records instead of telephone surveys and reported a small negative effect. The debate continues. So how could a higher minimum wage fail to reduce jobs? One explanation is monopsony, a situation in which employers have so much power over wages that they pay workers less than the value of their work. If a few big employers dominate a local labor market, a higher minimum can raise wages without destroying jobs. Another is that employers adjust in other ways, such as small price increases, or lower turnover, which saves hiring costs. Most economists now say that the answer depends on the size of the increase relative to local wages. A moderate rise in a low-wage region barely changes hiring. A large rise, in a place where it would exceed what most workers earn, is likely to cost jobs.",
      qs: [
      { q: "What is the main topic of the lecture?", o: ["The reasons why New Jersey raised its minimum wage in the spring of 1992.","How fast-food restaurants decide how many workers to employ.","Why economists agree that minimum wages always reduce employment.","Evidence that challenged the standard prediction about the minimum wage."], a: 3, x: "Le cours part de la prédiction du manuel, puis présente l'étude de Card et Krueger et le débat qu'elle a lancé." },
      { q: "Why did Card and Krueger include restaurants in Pennsylvania?", o: ["They were the largest fast-food employers in the region.","They had been affected by the same wage increase one year earlier.","They were more likely to answer telephone surveys than other restaurants.","They gave a comparison with a state where the minimum wage was unchanged."], a: 3, x: "Pennsylvanie = groupe de comparaison : le salaire minimum n'y a pas changé." },
      { q: "How did Neumark and Wascher respond to the study?", o: ["They used payroll records and found a small negative effect.","They repeated the telephone survey and obtained the same result.","They showed that Card and Krueger had chosen the wrong states.","They proved that the textbook model was entirely correct."], a: 0, x: "Données de paie au lieu d'enquêtes téléphoniques ; léger effet négatif trouvé. Le débat continue." },
      { q: "What is monopsony?", o: ["A market in which a single worker supplies all of the labor.","A market where employers can pay workers less than their work is worth.","A situation in which the government directly sets the wages of all workers.","A market where employers compete to attract the best workers."], a: 1, x: "Quelques gros employeurs dominent et paient moins que la valeur du travail : un salaire minimum peut alors augmenter les salaires sans détruire d'emplois." },
      { q: "What does the professor suggest about the minimum wage and employment?", o: ["The effect is always positive in regions where wages are rather low.","The effect is too small to be measured reliably by economists.","The effect depends on the size of the rise compared with local wages.","The effect depends mostly on the price of fast food."], a: 2, x: "« the answer depends on the size of the increase relative to local wages » : faible hausse = peu d'effet, hausse très forte = pertes d'emplois probables." }
      ] },
    { id: "tzb015", diff: 3, g: "W", ctx: "Listen to part of a lecture in a humanities class.", text: "In the late seventeenth and eighteenth centuries, London had thousands of coffeehouses. For the price of a penny, which bought you a cup of coffee, you could sit for hours, read the newspapers provided by the owner, and join in conversation with strangers. Some people called them penny universities. Historians of ideas have taken them seriously, and the German philosopher Jürgen Habermas, in a book published in 1962, argued that coffeehouses, along with salons and journals, created a new public sphere: a space in which private individuals gathered to debate matters of common concern, and where status mattered less than the quality of the argument. Governments recognized the danger. In 1675, Charles the Second tried to close the coffeehouses, claiming that they were places where people spread false news and scandal about the government. The ban was withdrawn within days, after a public outcry. They were also commercial places. Many coffeehouses specialized: one would attract merchants dealing with shipping, another stock traders, another scientists. The most famous example is Lloyd's. Edward Lloyd's coffeehouse became the place where ship owners and the men who insured them exchanged news about voyages, and it grew into the insurance market that still bears his name. Now, scholars have criticized Habermas's picture as too rosy. Women were generally absent from coffeehouses, and the poor couldn't spare the time. The ideal of open debate was real, but it was open only to a limited group. Still, there's something we can take from the story. The way a society circulates information, whether through coffeehouses or social media, shapes what it can discuss, and who is allowed to join.",
      qs: [
      { q: "What is the main idea of the lecture?", o: ["Coffeehouses were mainly places where merchants bought and sold coffee beans.","Coffeehouses were important places for exchanging information and ideas.","Governments in the eighteenth century encouraged public debate.","Habermas believed that coffeehouses should be closed."], a: 1, x: "Le cours montre le rôle des cafés comme lieux de circulation de l'information et des idées, et en nuance la portée." },
      { q: "According to Habermas, what was distinctive about the public sphere?", o: ["The quality of an argument mattered more than a person's status.","Governments organized the debates and chose the topics for discussion.","Only educated men were invited to take part in debates.","Newspapers were free for anyone who entered a coffeehouse."], a: 0, x: "Selon Habermas : des particuliers débattent d'affaires d'intérêt commun, et la qualité de l'argument compte plus que le statut." },
      { q: "Why did Charles the Second try to close the coffeehouses?", o: ["He wanted to protect the business of the taverns and inns of London.","He thought that the merchants there were avoiding their taxes in secret.","He feared that foreign merchants would use them to trade in secret.","He believed they spread false news and scandal about the government."], a: 3, x: "Il y voyait des lieux de propagation de fausses nouvelles et de scandales ; l'interdiction fut retirée en quelques jours." },
      { q: "Why does the professor mention Lloyd's?", o: ["To prove that coffeehouses were mainly meeting places for insurers.","To illustrate how the government supported commercial coffeehouses.","To show a coffeehouse developing into a major business institution.","To explain why coffeehouses were open to people of all classes."], a: 2, x: "Le café d'Edward Lloyd est devenu un marché de l'assurance : exemple de la dimension commerciale des cafés." },
      { q: "What is the professor's attitude toward Habermas's account?", o: ["It is false because coffeehouses were never open to the public at all.","It has some value, though it paints an overly positive picture.","It is accurate and has not been seriously criticized.","It is mostly about social media, not about coffeehouses."], a: 1, x: "Elle reprend la critique (« too rosy ») mais en tire une leçon : la circulation de l'information détermine ce dont une société peut discuter et qui peut participer." }
      ] },
    { id: "tzb016", diff: 4, g: "M", ctx: "Listen to part of a lecture in an accounting class.", text: "Accounting looks neutral, but its rules can shape the behavior of markets. Take the question of how a bank values the securities it holds. Under historical cost, an asset stays on the books at the price you paid for it, whatever happens afterward. Under fair value, often called mark-to-market, you revalue it each period at the price it would fetch in the market today. Fair value gives investors timely information, whereas historical cost can keep a rotten asset on the books at its original value for years. That was a big reason standard setters moved toward fair value in the 1990s. But in the 2008 crisis, fair value became controversial. When the market for mortgage-backed securities froze, the only available prices came from forced sales, at values far below what the cash flows might eventually justify. Banks had to write their assets down to those prices, which reduced their capital, which forced them to sell more assets, which pushed prices down further. Critics said that accounting had turned a panic into a spiral. Defenders replied that the rule hadn't created the losses, only revealed them, and that a bank with hidden losses is more dangerous, not less. In 2009, the American standard setter issued guidance giving firms more room for judgment where markets were inactive. So who is right? I'd say both are, in part. The measurement was honest, but it was a snapshot of a market in panic, and treating that snapshot as the true value is itself a judgment. There is no neutral way to measure value when the market can't agree on a price. Every choice of rule shifts the risk from one place to another: with historical cost, toward investors who can't see the problem; with fair value, toward a financial system that has to live with prices set in a panic.",
      qs: [
      { q: "What is the main point of the lecture?", o: ["Fair value accounting caused the 2008 financial crisis.","Historical cost accounting is more accurate than fair value in all circumstances.","Each accounting rule for valuing assets has costs, so no choice is neutral.","Standard setters should stop revising rules after a financial crisis."], a: 2, x: "Conclusion : chaque règle déplace le risque ailleurs, aucune n'est neutre. Le cours ne rend pas la juste valeur responsable de la crise." },
      { q: "How does fair value differ from historical cost?", o: ["Fair value uses the cash flows of an asset, while historical cost uses its market price.","Fair value applies only to banks, while historical cost applies to other companies.","Fair value is updated every year, while historical cost is updated every quarter.","Fair value uses today's market price, while historical cost keeps the price paid."], a: 3, x: "Historical cost : le prix payé ; fair value : le prix actuel du marché, réévalué à chaque période." },
      { q: "According to the critics, how did fair value accounting make the crisis worse?", o: ["Write-downs cut capital, forcing banks to sell assets and pushing prices lower.","Banks hid their losses from investors, which delayed the market's response.","Banks stopped lending because the rule required them to hold more cash.","The rule prevented banks from selling assets at prices that they considered unfair."], a: 0, x: "Spirale : écritures de dépréciation, baisse des fonds propres, ventes forcées, nouvelle baisse des prix." },
      { q: "What argument did the defenders of fair value make?", o: ["The rule helped banks to avoid selling their assets during the panic.","The rule gave managers more freedom to decide the value of assets.","The rule was necessary because historical cost is easy for banks to manipulate.","The rule revealed losses that already existed; hidden losses are worse."], a: 3, x: "« the rule hadn't created the losses, only revealed them » : cacher les pertes est plus dangereux." },
      { q: "What does the professor mean by saying that treating a snapshot as the true value \"is itself a judgment\"?", o: ["Accountants cannot photograph a market's prices without making errors.","Standard setters must always decide when a market is in panic.","Prices set in a panic may not reflect an asset's underlying worth.","Investors should not rely on the prices of assets in any market."], a: 2, x: "Un cliché pris en pleine panique n'est qu'un moment ; le retenir comme valeur vraie est un choix, d'où l'absence de mesure neutre quand le marché ne s'accorde pas sur un prix." }
      ] }
  );
})();
